/* VOORBEELDVRAGEN fiscaal: schenken, erven, box 3, partners en estate planning rond de woning (vbf-001 t/m vbf-100). */
window.VRAGEN_DATA=(window.VRAGEN_DATA||[]).concat([
 {id:'vbf-001',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2025-10-01T18:35:00',views:192,tags:['schenking','eigen middelen','dossier'],beste:'vbf-001-a1',
  titel:'Schenking van ouders als eigen geld bij aankoop: wat leg ik vast',
  body:`Een starter krijgt van de ouders een flink bedrag geschonken om de aankoop van de eerste woning mee te financieren. De geldverstrekker vraagt om bewijs van herkomst van de eigen middelen. Welke stukken nemen jullie standaard op in het dossier bij een schenking?`,
  antwoorden:[
   {id:'vbf-001-a1',auteur:'u1',datum:'2025-10-02T07:05:00',rA:{u2:4,u8:5},rAdv:{},body:`Ik vraag altijd een getekende schenkingsovereenkomst of schenkingsverklaring van de ouders, plus een bankafschrift waarop de overboeking zichtbaar is.
- Controleer de acceptatievoorwaarden van de geldverstrekker: sommige willen dat het geld al op de rekening van de klant staat, andere accepteren een verklaring vooraf.
- Leg vast of het een schenking is of een lening, dat maakt verschil voor de maandlasten en de toetsing.
- Wijs de klant erop dat hij zelf aangifte schenkbelasting moet doen als de schenking boven de actuele vrijstelling uitkomt.
In het dossier noteer ik ook dat ik de klant op die aangifteplicht heb gewezen.`},
   {id:'vbf-001-a2',auteur:'u8',datum:'2025-10-03T04:15:00',rA:{u5:5,u1:3,u4:4,u2:5},rAdv:{u5:5,u4:4},body:`Vanuit compliance nog een aanvulling: de herkomst van de middelen is ook een Wwft-aandachtspunt. Leg vast dat je de herkomst bij de schenkers hebt nagevraagd en dat het verhaal consistent is met de bankafschriften. Bij grote contante stortingen of overboekingen uit het buitenland vraag je door en noteer je wat je hebt gedaan.`}
  ]},
 {id:'vbf-002',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2025-10-04T10:40:00',views:580,tags:['schenkvrijstelling','eigen woning','jubelton'],beste:'vbf-002-a1',
  titel:'Eenmalig verhoogde schenkvrijstelling na afschaffing jubelton',
  body:`Een klant van eind twintig vraagt of de ouders nog belastingvrij een groot bedrag kunnen schenken voor de eigen woning. Ik weet dat de verhoogde vrijstelling voor de eigen woning is afgeschaft. Welke mogelijkheden zijn er nog?`,
  antwoorden:[
   {id:'vbf-002-a1',auteur:'u2',datum:'2025-10-04T17:50:00',rA:{u4:5},rAdv:{},body:`Klopt, de verhoogde vrijstelling specifiek voor de eigen woning bestaat sinds 2024 niet meer. Wat nog wel bestaat is de eenmalig verhoogde vrijstelling voor kinderen in een bepaalde leeftijdscategorie, zonder bestedingsdoel, en de verhoogde vrijstelling voor een dure studie.
- Controleer of de klant binnen de leeftijdsgrens valt en of er eerder al een beroep op een verhoogde vrijstelling is gedaan.
- De vrijstelling moet in de aangifte schenkbelasting worden geclaimd.
- Kijk bij de actuele normen van de Belastingdienst voor de bedragen.
Daarnaast kun je een lening van de ouders combineren met jaarlijkse schenkingen; dat werkt vaak beter dan één grote schenking.`},
   {id:'vbf-002-a2',auteur:'u5',datum:'2025-10-05T06:20:00',rA:{u4:5},rAdv:{u4:5},body:`Eens met Mark. Ik leg in het dossier vast dat ik de klant heb verwezen naar de actuele vrijstellingen en dat ik geen fiscaal advies over de aangifte zelf geef. Bij twijfel over eerdere schenkingen verwijs ik naar de notaris of een belastingadviseur.`}
  ]},
 {id:'vbf-003',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2025-10-08T15:10:00',views:529,tags:['familiehypotheek','eigenwoningschuld','renteaftrek'],beste:'vbf-003-a1',
  titel:'Lening van ouders als eigenwoningschuld: welke voorwaarden controleren jullie',
  body:`Ouders willen hun dochter een deel van de woning financieren via een onderhandse lening. De dochter wil de rente aftrekken. Waar moet de leningsovereenkomst minimaal aan voldoen?`,
  antwoorden:[
   {id:'vbf-003-a1',auteur:'u5',datum:'2025-10-08T21:10:00',rA:{u1:5},rAdv:{u1:5},body:`Voor renteaftrek moet de lening aan de voorwaarden voor een eigenwoningschuld voldoen.
- Er moet een schriftelijke leningsovereenkomst zijn met hoofdsom, rente, looptijd en aflossingsschema.
- De lening moet minimaal annuïtair of lineair worden afgelost binnen de wettelijke maximale looptijd.
- De rente moet zakelijk zijn; leg vast hoe je die hebt onderbouwd, bijvoorbeeld met een vergelijkbare marktrente.
- De lener moet de gegevens van de lening tijdig aan de Belastingdienst doorgeven.
Ik adviseer om de overeenkomst door een notaris te laten opstellen of in ieder geval te laten toetsen.`},
   {id:'vbf-003-a2',auteur:'u1',datum:'2025-10-09T07:00:00',rA:{u8:4,u4:3,u7:4,u5:4},rAdv:{u4:3,u7:4},body:`Let ook op de hypothecaire toets: de geldverstrekker telt de maandlasten van de familielening vaak mee in de leencapaciteit. Controleer de voorwaarden van de geldverstrekker of een achtergestelde lening van familie wordt geaccepteerd en hoe die wordt meegenomen.`}
  ]},
 {id:'vbf-004',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2025-10-11T20:30:00',views:509,tags:['familiehypotheek','kwijtschelding','schenking'],beste:null,
  titel:'Rente kwijtschelden aan kind: telt dat als schenking',
  body:`Ouders hebben een lening aan hun zoon verstrekt voor de eigen woning. Ze willen de jaarlijkse rente laten ontvangen en daarna een deel terugschenken. Andere ouders vragen of ze de rente simpelweg niet hoeven te innen. Hoe kijken jullie hiertegen aan?`,
  antwoorden:[
   {id:'vbf-004-a1',auteur:'u2',datum:'2025-10-12T09:30:00',rA:{u5:4,u1:4,u7:4},rAdv:{u5:5,u1:4},body:`Rente niet innen is in feite kwijtschelden, en dat is een schenking. Het grootste risico zit bij het kind: aftrek is alleen mogelijk voor rente die echt is betaald. Wordt de rente niet betaald, dan is er geen aftrek, en kan de Belastingdienst ook twijfelen of de lening zakelijk is.
De gangbare route:
- Leg de lening schriftelijk vast met zakelijke rente en een aflossingsschema dat aan de aflossingseis voldoet.
- Het kind betaalt de rente en aflossing daadwerkelijk per bank.
- De ouders kunnen later zelfstandig besluiten een bedrag te schenken. Er mag geen voorafgaande afspraak zijn dat de rente wordt teruggeschonken.
- Vermeld de lening in de aangifte (ook de ouders in box 3).
Leg in het dossier vast: de leningsovereenkomst, betalingsbewijs en dat je het verschil tussen kwijtschelden en schenken hebt uitgelegd.`}
  ]},
 {id:'vbf-005',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2025-10-15T17:20:00',views:134,tags:['schenking op papier','erfbelasting','notaris'],beste:'vbf-005-a1',
  titel:'Schenking op papier en rentebetaling: valkuilen bij overlijden',
  body:`Een echtpaar wil vermogen aan de kinderen schenken op papier, zodat de waardestijging van de woning buiten de nalatenschap blijft. Ze hebben echter weinig liquide middelen om de rente te betalen. Wat moet ik hen meegeven?`,
  antwoorden:[
   {id:'vbf-005-a1',auteur:'u2',datum:'2025-10-16T04:50:00',rA:{u7:5,u8:5,u1:5},rAdv:{u7:5},body:`Een schenking op papier moet bij notariële akte worden vastgelegd. De Successiewet stelt eisen aan de rente: die moet minimaal het wettelijk voorgeschreven percentage zijn en jaarlijks daadwerkelijk worden betaald. Wordt de rente niet betaald, dan kan de schuld bij overlijden fiscaal worden genegeerd en verlies je het voordeel. Ik rek met de klant door of de rentelast past bij het inkomen of vermogen, en leg vast dat de klant door de notaris over deze voorwaarden is geïnformeerd.`},
   {id:'vbf-005-a2',auteur:'u7',datum:'2025-10-16T09:50:00',rA:{u8:4,u2:5},rAdv:{u8:4},body:`Kijk ook naar de oudedagsvoorziening: de rente is voor de ouders een jaarlijkse uitgave tot het overlijden. Bij een krap pensioeninkomen kan dat knellen. Ik zou het altijd in een integraal financieel plan meenemen.`}
  ]},
 {id:'vbf-006',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2025-10-19T11:10:00',views:257,tags:['schenking','aflossen','boeterente'],beste:'vbf-006-a2',
  titel:'Jaarlijks schenken aan kinderen om hypotheek af te lossen',
  body:`Ouders willen hun twee kinderen jaarlijks een bedrag schenken, met de bedoeling dat ze daarmee extra aflossen op hun hypotheek. Hebben jullie tips voor de uitvoering?`,
  antwoorden:[
   {id:'vbf-006-a1',auteur:'u4',datum:'2025-10-20T06:30:00',rA:{u5:3},rAdv:{u5:3},body:`Praktisch: laat de kinderen eerst checken hoeveel ze per jaar boetevrij mogen aflossen volgens hun hypotheekvoorwaarden. Plan de schenking zo dat de aflossing binnen dat boetevrije deel valt. Controleer ook of extra aflossen invloed heeft op een eventuele rentekorting of een gekoppelde spaar- of beleggingsverzekering.`},
   {id:'vbf-006-a2',auteur:'u2',datum:'2025-10-20T17:10:00',rA:{u4:5},rAdv:{u4:5},body:`Aanvulling vanuit de planning: houd per kind bij wat er geschonken is, zodat je de jaarlijkse vrijstelling niet onbedoeld overschrijdt. Doen meerdere kinderen mee, overweeg dan een schenkingsoverzicht in het dossier van de ouders.
- Leg vast of de schenking vrij besteedbaar is of onder voorwaarde van aflossing.
- Bespreek of een uitsluitingsclausule gewenst is, zeker bij kinderen die in gemeenschap van goederen zijn getrouwd.
De notaris kan zo een clausule opnemen in een schenkingsakte.`}
  ]},
 {id:'vbf-007',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2025-10-22T08:55:00',views:337,tags:['uitsluitingsclausule','schenking','huwelijksvermogensrecht'],beste:'vbf-007-a1',
  titel:'Uitsluitingsclausule bij schenking aan getrouwd kind',
  body:`Een klant wil een bedrag schenken aan haar zoon, die in gemeenschap van goederen is getrouwd. Ze wil voorkomen dat bij een scheiding de helft naar de schoondochter gaat. Is een uitsluitingsclausule dan voldoende?`,
  antwoorden:[
   {id:'vbf-007-a1',auteur:'u2',datum:'2025-10-22T21:25:00',rA:{u5:4},rAdv:{u5:4},body:`Een uitsluitingsclausule zorgt ervoor dat de schenking buiten een gemeenschap van goederen valt. De clausule moet bij de schenking worden gemaakt, bijvoorbeeld in een schenkingsakte of een schriftelijke schenkingsovereenkomst. Let op vermenging: als de zoon het geld op een gezamenlijke rekening zet of in de gezamenlijke woning steekt, ontstaat er een vergoedingsrecht en wordt het lastiger aantoonbaar. Ik adviseer om dit door de notaris te laten vastleggen en de besteding te documenteren.`},
   {id:'vbf-007-a2',auteur:'u5',datum:'2025-10-22T23:45:00',rA:{u8:5},rAdv:{},body:`Bij inbreng in een gezamenlijke woning laat ik in de hypotheekofferte en het dossier vastleggen welk deel uit privévermogen van de zoon komt. Dat helpt later bij een eventuele verdeling.`}
  ]},
 {id:'vbf-008',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2025-10-26T19:30:00',views:565,tags:['erfbelasting','schenking','overlijden'],beste:'vbf-008-a1',
  titel:'Schenking binnen half jaar voor overlijden',
  body:`Een cliënt is ernstig ziek en wil nog snel aan zijn kinderen schenken. Ik heb begrepen dat schenkingen vlak voor overlijden alsnog in de erfbelasting kunnen vallen. Hoe zit dat precies?`,
  antwoorden:[
   {id:'vbf-008-a1',auteur:'u2',datum:'2025-10-27T13:00:00',rA:{u1:5,u8:4},rAdv:{u1:5},body:`Klopt. Schenkingen aan onder meer kinderen en de partner die binnen 180 dagen voor overlijden zijn gedaan, worden voor de erfbelasting behandeld alsof ze zijn geërfd. De betaalde schenkbelasting wordt dan verrekend. Het voordeel van de schenkvrijstelling kan in dat geval vervallen, behalve bij bepaalde vrijgestelde schenkingen. Verwijs de cliënt bij deze situatie altijd naar de notaris; dit is maatwerk en emotioneel beladen.`},
   {id:'vbf-008-a2',auteur:'u8',datum:'2025-10-28T05:20:00',rA:{u4:3},rAdv:{u4:3},body:`Let in zo een situatie ook op de wilsbekwaamheid en eventuele druk vanuit familie. Leg vast wie het initiatief nam en dat de cliënt zelfstandig heeft besloten. Bij twijfel adviseer ik de notaris in te schakelen, die toetst dit ook.`}
  ]},
 {id:'vbf-009',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2025-10-29T20:25:00',views:327,tags:['kleinkinderen','schenkbelasting','tarief'],beste:null,
  titel:'Schenken aan kleinkinderen: tarief en vrijstelling',
  body:`Grootouders willen hun kleinkinderen een bedrag schenken voor studie en een eerste woning. Gelden dezelfde vrijstellingen als voor kinderen?`,
  antwoorden:[
   {id:'vbf-009-a1',auteur:'u2',datum:'2025-10-30T00:35:00',rA:{u8:5},rAdv:{u8:5},body:`Nee, voor kleinkinderen geldt de algemene vrijstelling, die lager is dan de vrijstelling voor kinderen, en een hoger tarief. Een alternatief is dat de grootouders aan hun eigen kinderen schenken, die op hun beurt aan de kleinkinderen schenken, maar dat moet wel twee echte, afzonderlijke schenkingen zijn. Kijk voor de actuele bedragen naar de tabellen van de Belastingdienst.`},
   {id:'vbf-009-a2',auteur:'u7',datum:'2025-10-30T17:05:00',rA:{u3:4,u8:3},rAdv:{u3:4},body:`Bij minderjarige kleinkinderen komt het geld onder bewind van de ouders als wettelijk vertegenwoordiger. Wil je dat voorkomen, dan kan in de schenkingsakte een bewind worden ingesteld. Ook dat is notariswerk.`}
  ]},
 {id:'vbf-010',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2025-11-02T19:35:00',views:255,tags:['schenking','echtscheiding','herroeping'],beste:null,
  titel:'Schenking terugvorderen na scheiding van het kind',
  body:`Ouders hebben een paar jaar geleden een bedrag aan zoon en schoondochter samen geschonken voor de verbouwing van de woning. Nu gaan ze scheiden. Kunnen de ouders het deel van de schoondochter terugvragen?`,
  antwoorden:[
   {id:'vbf-010-a1',auteur:'u5',datum:'2025-11-03T08:45:00',rA:{u8:4},rAdv:{},body:`In principe is een schenking onherroepelijk, tenzij er een voorwaarde of herroepingsclausule is opgenomen. Als de schenking aan beiden is gedaan, is de schoondochter eigenaar van haar deel. Vraag of er een akte of schriftelijke overeenkomst is; daar staat de afspraak in. Laat dit door een advocaat of notaris beoordelen, dit valt buiten ons advies.`},
   {id:'vbf-010-a2',auteur:'u1',datum:'2025-11-03T21:45:00',rA:{u7:5,u4:3},rAdv:{},body:`Voor de hypotheek is vooral van belang hoe de woning wordt verdeeld. Ik leg vast welke afspraken in het echtscheidingsconvenant staan en of de partner die blijft de woning kan overnemen.`}
  ]},
 {id:'vbf-011',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2025-11-06T20:30:00',views:100,tags:['oversluiten','schenking','eigen middelen'],beste:'vbf-011-a1',
  titel:'Gift van ouders bij oversluiten: opgeven als eigen middelen',
  body:`Bij het oversluiten van een hypotheek willen de ouders bijspringen zodat de klant een lager bedrag hoeft te lenen. Hoe neem ik dat op in het advies?`,
  antwoorden:[
   {id:'vbf-011-a1',auteur:'u4',datum:'2025-11-07T04:00:00',rA:{u3:4,u7:5},rAdv:{},body:`Ik neem de schenking op als eigen middelen in de financieringsopzet. Controleer daarbij:
- of het geld vóór het passeren beschikbaar is op de rekening van de klant;
- of de geldverstrekker een verklaring van de schenkers wil;
- of de lagere hypotheek gevolgen heeft voor de verdeling van de eigenwoningschuld en een eventuele bijleenregeling.
Leg in het dossier het bedrag, de schenkers en het bewijs van ontvangst vast.`},
   {id:'vbf-011-a2',auteur:'u6',datum:'2025-11-07T21:10:00',rA:{u3:4,u7:3,u4:5},rAdv:{u3:4},body:`In het adviespakket kun je de schenking onder Eigen geld als aparte post toevoegen met de omschrijving schenking. Dan is het in het adviesrapport ook duidelijk terug te vinden.`}
  ]},
 {id:'vbf-012',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2025-11-09T20:05:00',views:501,tags:['kwijtschelding','schenking','lening'],beste:'vbf-012-a1',
  titel:'Schenken door middel van kwijtschelding van een lening',
  body:`Ouders hebben het kind in het verleden een lening verstrekt en willen nu jaarlijks een deel van de schuld kwijtschelden. Moet dat bij de notaris en hoe wordt dat aangegeven?`,
  antwoorden:[
   {id:'vbf-012-a1',auteur:'u2',datum:'2025-11-10T05:55:00',rA:{u4:3},rAdv:{u4:3},body:`Kwijtschelding van een schuld is fiscaal een schenking. Het hoeft niet per se bij de notaris, maar leg het schriftelijk vast, bij voorkeur met een getekende verklaring per jaar. Als de kwijtschelding boven de vrijstelling uitkomt, moet het kind aangifte schenkbelasting doen. Let op: als de lening een eigenwoningschuld is, verandert het aflossingsschema door de kwijtschelding; controleer of de schuld nog aan de voorwaarden voldoet en leg dat vast.`},
   {id:'vbf-012-a2',auteur:'u5',datum:'2025-11-11T01:05:00',rA:{u3:5},rAdv:{},body:`Eens. Ik pas na een kwijtschelding ook het overzicht van de eigenwoningschuld in het dossier aan, zodat de klant bij de aangifte inkomstenbelasting de juiste stand opgeeft.`}
  ]},
 {id:'vbf-013',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2025-11-13T18:20:00',views:495,tags:['contant geld','schenking','Wwft'],beste:null,
  titel:'Contant geld schenken van ouders',
  body:`Een klant wil een schenking van de ouders inbrengen die deels contant is gegeven. De geldverstrekker vraagt kritisch door. Hoe gaan jullie hiermee om?`,
  antwoorden:[
   {id:'vbf-013-a1',auteur:'u2',datum:'2025-11-14T09:15:00',rA:{u5:4,u1:5,u8:4},rAdv:{u1:4,u8:5},body:`Contant geld is bij geldverstrekkers en notarissen een rode vlag vanwege witwasregels. De klant moet de herkomst aantonen, anders telt het bedrag meestal niet mee.
- Laat het geld storten op de rekening van de klant en vraag bewijs van herkomst bij de ouders: bankafschriften met de opname, of een spaarrekening.
- Laat een schenkingsakte of verklaring opstellen en doe aangifte schenkbelasting als dat nodig is.
- Contant geld dat lang thuis heeft gelegen zonder bewijs, is lastig. Wees daar terughoudend in.
Adviseer klanten bij voorkeur om schenkingen per bank te doen. Leg in het dossier vast welke bewijsstukken je hebt ontvangen en hoe je de herkomst hebt beoordeeld. Bij twijfel overleg je met je compliance officer.`}
  ]},
 {id:'vbf-014',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2025-11-17T20:35:00',views:198,tags:['schoonkind','schenkvrijstelling','schenking'],beste:'vbf-014-a1',
  titel:'Schenking aan schoonkind in plaats van aan eigen kind',
  body:`Ouders willen een schenking doen aan hun dochter en haar partner samen. Ik hoor wisselende verhalen over de vrijstelling voor het schoonkind. Wat is de lijn?`,
  antwoorden:[
   {id:'vbf-014-a1',auteur:'u2',datum:'2025-11-18T07:15:00',rA:{u4:4,u1:4},rAdv:{},body:`Ga er niet van uit dat de partner van het kind automatisch dezelfde vrijstelling en hetzelfde tarief heeft als het eigen kind. Dat hangt af van de relatie en de actuele regels; laat het per situatie toetsen. Ik adviseer om in de schenkingsovereenkomst per ontvanger te vermelden welk bedrag wordt geschonken. Zo voorkom je discussies bij de aangifte en bij een eventuele scheiding.`},
   {id:'vbf-014-a2',auteur:'u8',datum:'2025-11-18T09:55:00',rA:{u7:3,u1:4},rAdv:{u7:3},body:`Leg in het dossier vast dat de klant voor de fiscale kwalificatie is doorverwezen naar notaris of belastingadviseur als je dat zelf niet zeker kunt vaststellen.`}
  ]},
 {id:'vbf-015',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2025-11-20T11:55:00',views:37,tags:['bewind','schenking','notaris'],beste:'vbf-015-a2',
  titel:'Bewind in schenkingsakte voor jong volwassen kind',
  body:`Een klant wil haar zoon van begin twintig een behoorlijk bedrag schenken, maar twijfelt of hij er verstandig mee omgaat. Kan zij voorwaarden stellen aan de besteding?`,
  antwoorden:[
   {id:'vbf-015-a1',auteur:'u7',datum:'2025-11-20T16:45:00',rA:{u8:3,u2:5,u5:4},rAdv:{u5:4},body:`Ze kan een schenking doen onder voorwaarden, bijvoorbeeld dat het geld alleen voor een woning of studie mag worden gebruikt. Hoe afdwingbaar dat is, hangt af van de formulering.`},
   {id:'vbf-015-a2',auteur:'u2',datum:'2025-11-21T00:25:00',rA:{u4:3,u1:4},rAdv:{},body:`Een sterkere route is een testamentair of contractueel bewind in de schenkingsakte, waarbij een bewindvoerder het geld beheert tot een bepaalde leeftijd. Dat is notariswerk. Leg in het dossier vast wat het doel van de klant is en welke alternatieven je hebt besproken, bijvoorbeeld een lening in plaats van een schenking. Een lening biedt de ouders meer grip, omdat ze later nog kunnen kwijtschelden.`}
  ]},
 {id:'vbf-016',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2025-11-24T20:35:00',views:385,tags:['vruchtgebruik','woning','schenking'],beste:'vbf-016-a1',
  titel:'Schenking van woning aan kind met voorbehoud van vruchtgebruik',
  body:`Oudere klanten willen hun vrijstaande woning aan de kinderen schenken, maar er zelf blijven wonen. Ze denken aan het voorbehouden van het vruchtgebruik. Wat zijn de aandachtspunten?`,
  antwoorden:[
   {id:'vbf-016-a1',auteur:'u2',datum:'2025-11-25T05:25:00',rA:{u7:4,u1:4,u3:4},rAdv:{u7:4,u1:4},body:`Dit is een complexe constructie waarbij je de notaris en een fiscalist nodig hebt.
- Het bloot eigendom wordt geschonken; de waarde wordt bepaald volgens de regels van de Successiewet.
- Er gelden antimisbruikbepalingen voor voorbehouden vruchtgebruik, waardoor het fiscale voordeel tegen kan vallen.
- De ouders blijven verantwoordelijk voor de lasten; de kinderen worden juridisch eigenaar.
- Een eventuele hypotheek moet mee worden genomen; controleer de voorwaarden van de geldverstrekker.
Ik leg vast dat ik deze punten heb besproken en heb doorverwezen.`},
   {id:'vbf-016-a2',auteur:'u5',datum:'2025-11-25T19:15:00',rA:{},rAdv:{},body:`Let ook op box 3 en de eigenwoningregeling: na de schenking verandert de fiscale positie van ouders én kinderen. Laat de fiscalist een totaalberekening maken voordat de akte wordt gepasseerd.`}
  ]},
 {id:'vbf-017',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2025-11-27T18:45:00',views:77,tags:['periodieke gift','ANBI','giftenaftrek'],beste:null,
  titel:'Schenking aan goed doel via periodieke gift',
  body:`Een klant heeft na verkoop van zijn woning ruimte en wil jaarlijks een vast bedrag aan een goed doel geven. Wat is fiscaal de handigste manier?`,
  antwoorden:[
   {id:'vbf-017-a1',auteur:'u2',datum:'2025-11-28T05:55:00',rA:{u7:4},rAdv:{},body:`Een periodieke gift aan een ANBI, vastgelegd in een schriftelijke overeenkomst met de instelling of bij notariële akte, is in box 1 volledig aftrekbaar zonder drempel, mits de looptijd en voorwaarden kloppen. Controleer of de instelling de ANBI-status heeft. Leg in het plan vast dat de gift is meegenomen in het besteedbaar inkomen voor de komende jaren.`}
  ]},
 {id:'vbf-018',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2025-12-01T16:45:00',views:428,tags:['schenkbelasting','brutering','aangifte'],beste:'vbf-018-a1',
  titel:'Schenkbelasting betalen door de schenker in plaats van ontvanger',
  body:`Ouders willen de schenkbelasting voor hun kind betalen. Mag dat zomaar en heeft dat gevolgen?`,
  antwoorden:[
   {id:'vbf-018-a1',auteur:'u2',datum:'2025-12-01T21:25:00',rA:{u4:5},rAdv:{},body:`Als de schenker de belasting betaalt, is dat in feite een extra schenking. De Successiewet regelt dat de belasting dan over het gebruteerde bedrag wordt berekend, wat leidt tot een hogere heffing. Spreek dit vooraf af en laat het opnemen in de schenkingsovereenkomst. De aangifte blijft op naam van de ontvanger.`},
   {id:'vbf-018-a2',auteur:'u8',datum:'2025-12-02T12:55:00',rA:{u4:4,u7:5},rAdv:{u7:5},body:`Leg in het dossier vast dat je dit hebt gesignaleerd en wie de aangifte verzorgt. Ik zie in reviews regelmatig dat onduidelijk is wie welke actie zou doen.`}
  ]},
 {id:'vbf-019',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2025-12-05T13:00:00',views:10,tags:['schenking','termijnen','akte'],beste:'vbf-019-a1',
  titel:'Schenking in termijnen vastleggen',
  body:`Ouders willen hun kind een groot bedrag schenken, maar het geld komt pas over enkele jaren vrij uit een beleggingsdepot. Kunnen zij de schenking nu al vastleggen?`,
  antwoorden:[
   {id:'vbf-019-a1',auteur:'u2',datum:'2025-12-05T20:20:00',rA:{u5:5},rAdv:{},body:`Dat kan met een schenking op papier bij notariële akte: de schenking ontstaat nu, de uitbetaling volgt later. Let op de renteverplichting en de eisen uit de Successiewet. Alternatief is om nu niets vast te leggen en per jaar te schenken wanneer het geld beschikbaar is. Ik leg in het plan vast welke variant de klant kiest en waarom.`},
   {id:'vbf-019-a2',auteur:'u4',datum:'2025-12-06T02:10:00',rA:{u7:5,u3:5,u1:4},rAdv:{},body:`Voor de hypotheek telt een toekomstige schenking meestal niet als eigen middelen; de geldverstrekker kijkt naar wat bij passeren beschikbaar is. Controleer de voorwaarden van de geldverstrekker voordat de klant ermee rekent.`}
  ]},
 {id:'vbf-020',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2025-12-08T10:40:00',views:470,tags:['studie','schenkvrijstelling','studieschuld'],beste:'vbf-020-a1',
  titel:'Schenking voor dure studie en aflossen studieschuld',
  body:`Een klant heeft een studieschuld en de ouders willen die aflossen. Valt dat onder de verhoogde vrijstelling voor een dure studie?`,
  antwoorden:[
   {id:'vbf-020-a1',auteur:'u7',datum:'2025-12-09T03:00:00',rA:{u8:5,u4:5},rAdv:{},body:`De verhoogde vrijstelling voor een dure studie is bedoeld voor studiekosten die nog moeten worden gemaakt, niet voor het aflossen van een bestaande schuld. Voor aflossing van de studieschuld kan wel de reguliere of eenmalig verhoogde vrijstelling worden gebruikt, als de klant daaraan voldoet. Controleer de actuele voorwaarden. Voor de hypotheek is aflossing van de studieschuld interessant omdat die meeweegt in de leencapaciteit.`},
   {id:'vbf-020-a2',auteur:'u1',datum:'2025-12-09T21:40:00',rA:{u8:3},rAdv:{},body:`Klopt, ik reken in dat geval altijd twee scenario's door: met en zonder afgeloste studieschuld. Leg in het dossier vast welke variant is besproken.`}
  ]},
 {id:'vbf-021',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2025-12-12T20:35:00',views:545,tags:['samenwonen','schenking','vergoedingsrecht'],beste:null,
  titel:'Inbreng schenking in woning bij ongehuwd samenwonen',
  body:`Een ongehuwd stel koopt samen een huis. Een van beiden krijgt een grote schenking van de ouders en brengt die in. Hoe beschermen we die inbreng?`,
  antwoorden:[
   {id:'vbf-021-a1',auteur:'u5',datum:'2025-12-13T00:05:00',rA:{u1:4},rAdv:{},body:`Leg in het samenlevingscontract of een aparte overeenkomst vast dat de ingebrachte middelen een vordering opleveren op de ander. Een alternatief is een ongelijke eigendomsverhouding in de leveringsakte. Bespreek beide varianten met de notaris en noteer in het dossier welke keuze is gemaakt. Let op: een ongelijke eigendomsverhouding heeft gevolgen voor de verdeling van de eigenwoningschuld en de renteaftrek.`},
   {id:'vbf-021-a2',auteur:'u1',datum:'2025-12-13T21:25:00',rA:{u7:4},rAdv:{},body:`Bij het passeren vraag ik de notaris altijd naar de eigendomsverhouding en ik zet die ook in de adviesrapportage.`}
  ]},
 {id:'vbf-022',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2025-12-15T09:25:00',views:60,tags:['schenking','ontbindende voorwaarde','aankoop'],beste:null,
  titel:'Schenking terugbetalen bij afwijzing hypotheek',
  body:`Ouders hebben al geschonken voor een woning, maar de financiering gaat niet door. Het kind wil het geld teruggeven. Hoe zit het dan met de schenkbelasting?`,
  antwoorden:[
   {id:'vbf-022-a1',auteur:'u2',datum:'2025-12-16T09:05:00',rA:{u5:4,u1:4,u7:4},rAdv:{u5:4,u1:4},body:`Dat hangt af van hoe de schenking is gedaan.
- Schenking onder een ontbindende voorwaarde, bijvoorbeeld dat de woning wordt gekocht: valt de voorwaarde weg, dan wordt de schenking ontbonden en is terugbetalen geen nieuwe schenking. Kijk of dit in de akte of schriftelijke verklaring staat.
- Onvoorwaardelijke schenking: dan is teruggeven aan de ouders in principe een nieuwe schenking van kind aan ouders, waarover schenkbelasting kan worden geheven boven de vrijstelling.
- Is er al aangifte gedaan met een beroep op een vrijstelling met voorwaarden, controleer dan of die vrijstelling vervalt.
Laat de ouders en het kind dit vóór terugbetaling met een notaris of fiscalist bespreken. Leg vast dat je hierop hebt gewezen en welke documenten er zijn.`}
  ]},
 {id:'vbf-023',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2025-12-19T18:40:00',views:353,tags:['gelijke behandeling','schenking','testament'],beste:'vbf-023-a1',
  titel:'Gelijke behandeling kinderen bij schenking aan één kind',
  body:`Ouders schenken één kind een groot bedrag voor een woning. De andere kinderen krijgen nu niets. Hoe zorgen ze dat het bij de nalatenschap eerlijk wordt?`,
  antwoorden:[
   {id:'vbf-023-a1',auteur:'u2',datum:'2025-12-20T11:20:00',rA:{u8:4,u5:4},rAdv:{u5:4},body:`Er zijn twee routes. De ouders kunnen bij de schenking bepalen dat deze moet worden ingebracht bij de verdeling van de nalatenschap; dan wordt er later mee verrekend. Ze kunnen ook de andere kinderen nu al gelijkwaardig bedenken of in het testament een compensatie regelen. Laat dit vastleggen in de schenkingsakte of het testament. Ik leg in het dossier vast welke afspraak de ouders hebben gemaakt.`},
   {id:'vbf-023-a2',auteur:'u8',datum:'2025-12-20T23:50:00',rA:{u2:5,u7:4},rAdv:{u2:5},body:`Leg de wens tot gelijke behandeling expliciet vast. Bij klachten na overlijden is dat vaak het eerste waar naar wordt gevraagd.`}
  ]},
 {id:'vbf-024',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2025-12-23T11:10:00',views:36,tags:['buitenland','schenkbelasting','woonplaats'],beste:null,
  titel:'Schenking van ouders in het buitenland',
  body:`Een klant ontvangt een schenking van ouders die in het buitenland wonen. Moet hij hier schenkbelasting betalen?`,
  antwoorden:[
   {id:'vbf-024-a1',auteur:'u2',datum:'2025-12-23T19:30:00',rA:{u5:3,u4:4,u3:5},rAdv:{u5:3,u4:4,u3:5},body:`Voor de schenkbelasting is de woonplaats van de schenker bepalend. Wonen de ouders niet in Nederland en zijn ze geen Nederlanders die recent zijn geëmigreerd, dan is in Nederland meestal geen schenkbelasting verschuldigd. Het buitenland kan wel eigen regels hebben. Laat dit door een fiscalist beoordelen.`},
   {id:'vbf-024-a2',auteur:'u8',datum:'2025-12-24T07:20:00',rA:{u7:3,u2:4,u3:5,u5:3},rAdv:{u3:5},body:`Vanuit Wwft-perspectief: vraag bewijs van de herkomst en van de overboeking. Buitenlandse geldstromen vragen om extra aandacht in het dossier.`}
  ]},
 {id:'vbf-025',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2025-12-26T10:45:00',views:266,tags:['box 3','peildatum','schenking'],beste:'vbf-025-a1',
  titel:'Schenking rond de jaarwisseling en box 3 peildatum',
  body:`Ouders willen eind december een groot bedrag aan hun kind schenken. Ze vragen of het uitmaakt of ze dat voor of na 1 januari doen. Wat zeggen jullie?`,
  antwoorden:[
   {id:'vbf-025-a1',auteur:'u2',datum:'2025-12-26T16:35:00',rA:{u4:4,u5:3},rAdv:{u4:4},body:`Voor box 3 is de stand op 1 januari bepalend. Schenken de ouders vóór 1 januari, dan telt het bedrag bij hen niet meer mee en bij het kind wel. Daarnaast hoort de schenking bij het kalenderjaar waarin ze plaatsvindt, wat van belang is voor de jaarlijkse vrijstelling. Twee schenkingen rond de jaarwisseling kunnen dus twee keer van de jaarlijkse vrijstelling profiteren.
- Leg de datum van overboeking vast.
- Let op toeslagen of andere inkomensafhankelijke regelingen bij het kind.
Bespreek ook of het kind het geld daadwerkelijk wil aanhouden of direct aflost.`},
   {id:'vbf-025-a2',auteur:'u3',datum:'2025-12-27T09:25:00',rA:{},rAdv:{},body:`Goed punt over de toeslagen. Ik zie in de praktijk dat het vermogen van het kind soms net boven een vermogensgrens uitkomt. Even checken bij de actuele grenzen voorkomt een terugvordering.`}
  ]},
 {id:'vbf-026',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2025-12-31T19:40:00',views:40,tags:['erfrecht','wettelijke verdeling','langstlevende'],beste:'vbf-026-a1',
  titel:'Wettelijke verdeling en de hypotheek van de langstlevende',
  body:`Een weduwe wil na het overlijden van haar man de hypotheek oversluiten. Er is geen testament, dus de wettelijke verdeling is van toepassing. De kinderen hebben een vordering op haar. Hoe gaan jullie om met die vorderingen in de financieringsaanvraag?`,
  antwoorden:[
   {id:'vbf-026-a1',auteur:'u5',datum:'2025-12-31T22:34:00',rA:{},rAdv:{},body:`Bij de wettelijke verdeling krijgt de langstlevende echtgenoot alle goederen en krijgen de kinderen een geldvordering. Die vordering is in de regel pas opeisbaar bij overlijden of faillissement of schuldsanering van de langstlevende. Voor de acceptatie is het dus geen lopende verplichting met maandlasten.
- Vraag een verklaring van erfrecht op.
- Leg de hoogte van de kindsdelen vast in het dossier.
- Controleer de voorwaarden van de geldverstrekker over het meenemen van deze vorderingen.
Sommige geldverstrekkers willen zien dat de woning voldoende overwaarde houdt.`},
   {id:'vbf-026-a2',auteur:'u2',datum:'2026-01-01T21:18:00',rA:{u7:4},rAdv:{u7:4},body:`Bespreek ook of de kinderen rente op hun vordering krijgen. Zonder testamentaire regeling is de rente in de praktijk vaak nihil, maar als er wel rente is opgenomen loopt de vordering op. Dat raakt de vermogensplanning van de langstlevende op termijn.`}
  ]},
 {id:'vbf-027',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-01-07T19:45:00',views:91,tags:['erfenis','beneficiair','onderwaarde'],beste:'vbf-027-a1',
  titel:'Erfenis beneficiair aanvaarden bij woning met onderwaarde',
  body:`De erfgenamen van een overleden klant twijfelen of ze de erfenis moeten aanvaarden. De woning heeft mogelijk een hypotheek die hoger is dan de waarde. Wat adviseren jullie in zo een situatie?`,
  antwoorden:[
   {id:'vbf-027-a1',auteur:'u5',datum:'2026-01-08T00:15:00',rA:{u2:3},rAdv:{u2:3},body:`Beneficiair aanvaarden is in zo een geval vaak de veiligste route: de erfgenamen zijn dan in beginsel niet met hun eigen vermogen aansprakelijk voor de schulden van de nalatenschap. Daar hoort wel een vereffeningsprocedure bij met eigen regels.
- Laat de aanvaarding via de rechtbank of notaris lopen.
- Wees voorzichtig met handelingen die als zuivere aanvaarding kunnen gelden, zoals spullen verkopen.
- Leg vast dat je de erfgenamen hebt geadviseerd een notaris in te schakelen.
Wij geven hier geen juridisch advies, maar signaleren het risico.`},
   {id:'vbf-027-a2',auteur:'u3',datum:'2026-01-08T04:43:00',rA:{u1:3},rAdv:{u1:3},body:`Check ook of er een overlijdensrisicoverzekering aan de hypotheek gekoppeld was. De uitkering kan het tekort volledig wegnemen en dan ziet het plaatje er heel anders uit. Vraag de polisgegevens op en leg in het dossier vast of de uitkering al is aangevraagd.`}
  ]},
 {id:'vbf-028',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-01-08T15:15:00',views:531,tags:['testament','langstlevende','ongehuwd'],beste:null,
  titel:'Ongehuwd samenwonend zonder testament: erft de partner de woning',
  body:`Een stel woont al jaren ongehuwd samen in een gezamenlijke koopwoning. Er is een samenlevingscontract, maar geen testament. Erft de partner automatisch het aandeel van de ander?`,
  antwoorden:[
   {id:'vbf-028-a1',auteur:'u5',datum:'2026-01-09T08:01:00',rA:{},rAdv:{},body:`Nee. Ongehuwd samenwonenden zijn geen erfgenaam van elkaar volgens de wet. Zonder testament gaat het aandeel naar de wettelijke erfgenamen, zoals kinderen of ouders. Een verblijvingsbeding in het samenlevingscontract kan helpen, maar controleer of dat er goed in staat.
- Adviseer een testament en laat het samenlevingscontract door de notaris toetsen.
- Leg in het dossier vast dat je dit risico hebt besproken.
Kijk daarnaast naar de ORV: een kruislingse polis kan de partner financieel beschermen.`},
   {id:'vbf-028-a2',auteur:'u2',datum:'2026-01-10T03:09:00',rA:{u8:5},rAdv:{u8:5},body:`Voor de erfbelasting kan de partnervrijstelling gelden als aan de voorwaarden voor samenwoners wordt voldaan. Controleer de actuele voorwaarden, zoals de duur van de samenwoning en een notarieel samenlevingscontract met wederzijdse zorgverplichting. Leg in het dossier vast dat je dit punt hebt besproken en hebt doorverwezen naar de notaris.`}
  ]},
 {id:'vbf-029',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-01-13T10:20:00',views:332,tags:['erfbelasting','WOZ','woning'],beste:'vbf-029-a1',
  titel:'Welke waarde van de woning telt voor de erfbelasting',
  body:`Bij een nalatenschap is de woning onderdeel van de verkrijging. De erfgenamen vragen of de marktwaarde of de WOZ-waarde telt. Wat is gebruikelijk?`,
  antwoorden:[
   {id:'vbf-029-a1',auteur:'u2',datum:'2026-01-13T21:34:00',rA:{u1:4,u6:4,u8:4,u5:5},rAdv:{u1:4,u6:4,u5:5},body:`Voor een woning die de erflater zelf bewoonde, geldt voor de erfbelasting in de regel de WOZ-waarde die hoort bij het jaar van overlijden. Is de woning verhuurd, dan gelden andere waarderingsregels. Een hypotheek wordt als schuld van de nalatenschap afgetrokken.
- Vraag de WOZ-beschikking op.
- Leg vast welke waarde je in je berekeningen gebruikt.
Laat de aangifte erfbelasting bij twijfel door de notaris of een fiscalist verzorgen.`}
  ]},
 {id:'vbf-030',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-01-17T16:00:00',views:233,tags:['erfbelasting','aangifte','termijn'],beste:'vbf-030-a1',
  titel:'Termijn aangifte erfbelasting en invloed op hypotheekadvies',
  body:`Een klant heeft een erfenis gekregen en wil een deel inbrengen in de aankoop van een woning. De aangifte erfbelasting is nog niet gedaan. Moet ik daar rekening mee houden in de eigen middelen?`,
  antwoorden:[
   {id:'vbf-030-a1',auteur:'u2',datum:'2026-01-18T10:27:00',rA:{u8:5},rAdv:{},body:`Ja. De aangifte erfbelasting moet in de regel binnen acht maanden na overlijden worden ingediend, en de aanslag volgt later. Als de klant het hele bedrag inbrengt, moet de erfbelasting nog uit ander vermogen betaald kunnen worden.
- Reserveer een inschatting van de verschuldigde erfbelasting.
- Leg vast hoeveel van de erfenis vrij beschikbaar is.
Gebruik voor de inschatting de actuele tarieven en vrijstellingen.`},
   {id:'vbf-030-a2',auteur:'u1',datum:'2026-01-19T00:14:00',rA:{},rAdv:{},body:`Geldverstrekkers vragen vaak een verklaring van erfrecht en een bewijs dat het geld daadwerkelijk beschikbaar is. Is de nalatenschap nog niet afgewikkeld, controleer dan de voorwaarden van de geldverstrekker voor eigen middelen die nog niet op de rekening staan. Leg vast welke stukken je hebt gezien en dat je de klant op de aangifteplicht hebt gewezen.`}
  ]},
 {id:'vbf-031',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-01-20T14:20:00',views:366,tags:['legitieme portie','testament','kinderen'],beste:'vbf-031-a1',
  titel:'Kind onterfd: kan de legitieme portie de woning raken',
  body:`Een klant is door een ouder onterfd en overweegt zijn legitieme portie op te eisen. Hij vraagt of hij dan recht heeft op een deel van de woning van de overleden ouder. Hoe zit dat?`,
  antwoorden:[
   {id:'vbf-031-a1',auteur:'u5',datum:'2026-01-21T01:20:00',rA:{},rAdv:{},body:`De legitieme portie is een geldvordering, geen recht op een deel van de woning zelf. De erfgenamen moeten het bedrag betalen, maar de opeisbaarheid kan in sommige situaties worden uitgesteld, bijvoorbeeld als er een langstlevende echtgenoot is. Er geldt ook een vervaltermijn om een beroep op de legitieme te doen.
Laat de klant contact opnemen met een notaris of advocaat. Leg in het dossier vast dat de vordering onzeker is qua hoogte en moment, zodat je die niet als eigen middelen meeneemt.`}
  ]},
 {id:'vbf-032',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-01-25T08:35:00',views:252,tags:['erfenis','eigen middelen','verklaring van erfrecht'],beste:null,
  titel:'Erfenis gebruiken als eigen middelen: welke stukken vragen jullie op',
  body:`Een klant wil een recente erfenis gebruiken voor extra aflossing en verbouwing. Welke stukken leggen jullie standaard vast in het dossier?`,
  antwoorden:[
   {id:'vbf-032-a1',auteur:'u1',datum:'2026-01-26T02:44:00',rA:{u7:5,u8:5,u4:3},rAdv:{},body:`Wij vragen meestal op:
- een verklaring van erfrecht of een notariële verklaring over de verdeling;
- een bankafschrift waaruit de ontvangst blijkt;
- bij een grotere erfenis een toelichting op de herkomst.
Controleer altijd de voorwaarden van de geldverstrekker, want de eisen verschillen.`},
   {id:'vbf-032-a2',auteur:'u8',datum:'2026-01-26T11:58:00',rA:{u5:4},rAdv:{},body:`Vanuit Wwft-perspectief is de herkomst van middelen belangrijk. Een erfenis is goed te onderbouwen met de notariële stukken. Bewaar ze in het dossier en noteer wie de stukken heeft gecontroleerd.`}
  ]},
 {id:'vbf-033',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-02-04T10:15:00',views:275,tags:['vruchtgebruik','testament','woning'],beste:'vbf-033-a1',
  titel:'Vruchtgebruik van de woning voor de langstlevende en bloot eigendom voor kinderen',
  body:`Een testament geeft de langstlevende het vruchtgebruik van de woning en de kinderen het bloot eigendom. Nu wil de langstlevende de hypotheek verhogen voor een verbouwing. Kan dat zonder de kinderen?`,
  antwoorden:[
   {id:'vbf-033-a1',auteur:'u5',datum:'2026-02-04T14:20:00',rA:{u4:5,u7:4},rAdv:{u4:5,u7:4},body:`In de regel niet. Voor het vestigen van een hypotheekrecht op de volle eigendom zijn ook de bloot eigenaren nodig. Geldverstrekkers stellen bij vruchtgebruik vaak extra eisen of financieren niet.
- Lees het testament na op bevoegdheden van de vruchtgebruiker.
- Leg vast dat de kinderen akkoord zijn en mee moeten tekenen.
- Controleer de voorwaarden van de geldverstrekker voor vruchtgebruik.`}
  ]},
 {id:'vbf-034',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-02-11T07:25:00',views:509,tags:['erfbelasting','partnervrijstelling','gehuwd'],beste:null,
  titel:'Erfbelasting voor de langstlevende partner: wanneer is die verschuldigd',
  body:`Na het overlijden van een partner vraagt de langstlevende of zij erfbelasting moet betalen. Ze waren getrouwd in gemeenschap van goederen. Hoe leggen jullie dat kort uit?`,
  antwoorden:[
   {id:'vbf-034-a1',auteur:'u2',datum:'2026-02-12T00:02:00',rA:{},rAdv:{},body:`De langstlevende krijgt bij een huwelijk in gemeenschap van goederen de helft van de gemeenschap al op grond van het huwelijksvermogensrecht. Alleen wat zij uit de nalatenschap erft, valt onder de erfbelasting. Daarop is de partnervrijstelling van toepassing. Of er dan nog iets verschuldigd is, hangt af van de omvang van de verkrijging en de actuele vrijstelling.
Leg vast welke uitgangspunten je hebt gebruikt en verwijs naar de notaris voor de aangifte.`},
   {id:'vbf-034-a2',auteur:'u7',datum:'2026-02-12T05:37:00',rA:{},rAdv:{},body:`Let ook op het nabestaandenpensioen. Dat valt niet onder de erfbelasting, maar het is wel belangrijk voor de vraag of de woonlasten betaalbaar blijven. Maak een inkomensoverzicht na overlijden.`}
  ]},
 {id:'vbf-035',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-02-14T12:10:00',views:408,tags:['executeur','nalatenschap','afwikkeling'],beste:null,
  titel:'Rol van de executeur bij aflossen hypotheek na overlijden',
  body:`De executeur van een nalatenschap belt met de vraag of hij de hypotheek mag aflossen met geld uit de nalatenschap. Wat mag een executeur wel en niet?`,
  antwoorden:[
   {id:'vbf-035-a1',auteur:'u2',datum:'2026-02-15T10:20:00',rA:{u5:4,u7:4,u1:4},rAdv:{u5:5,u7:4},body:`De executeur beheert de nalatenschap en betaalt de schulden van de nalatenschap. Een hypotheekschuld is zo'n schuld. Of hij die mag aflossen, hangt af van zijn bevoegdheden in het testament en van de vraag of aflossing nodig is.
- Een gewone executeur heeft voor ingrijpende handelingen vaak toestemming van de erfgenamen nodig. Vraag de verklaring van executele of erfrecht op.
- Kijk wie de woning en schuld overneemt. Woont de langstlevende er, dan is aflossen niet altijd in zijn belang.
- Check bij de geldverstrekker of aflossen na overlijden boetevrij is en of er een ORV-uitkering komt.
- Bekijk de fiscale gevolgen voor het overgangsrecht van een eventuele voortzetting.
Laat de executeur zijn besluit schriftelijk vastleggen met instemming van de erfgenamen. Leg in je eigen dossier vast wie je opdrachtgever is en welke informatie je hebt gedeeld.`}
  ]},
 {id:'vbf-036',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-02-16T10:05:00',views:347,tags:['erfenis','renteaftrek','eigen woning'],beste:'vbf-036-a1',
  titel:'Renteaftrek voor erfgenamen als de woning leeg staat',
  body:`De woning van een overleden ouder staat leeg en wordt te koop gezet. Er rust nog een hypotheek op. Kunnen de kinderen de rente aftrekken?`,
  antwoorden:[
   {id:'vbf-036-a1',auteur:'u2',datum:'2026-02-16T19:52:00',rA:{u1:3,u8:3},rAdv:{u8:3},body:`De woning is voor de kinderen geen eigen woning, omdat zij er niet wonen. De woning en de schuld vallen bij de erfgenamen dan in box 3. In het jaar van overlijden kan de rente nog in de aangifte van de overledene worden meegenomen.
Controleer de actuele regels en laat de aangifte bij twijfel door een fiscalist doen. Leg in het dossier vast wat je hebt besproken.`}
  ]},
 {id:'vbf-037',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-02-19T09:15:00',views:99,tags:['testament','tweetrapsmaking','kleinkinderen'],beste:'vbf-037-a1',
  titel:'Tweetrapsmaking: wanneer bespreken jullie dat met klanten',
  body:`Een oudere klant wil haar vermogen ooit aan een goed doel of aan haar kleinkinderen nalaten, maar haar zus moet eerst zorg hebben. Ik hoorde over een tweetrapsmaking. Wanneer is dat zinvol?`,
  antwoorden:[
   {id:'vbf-037-a1',auteur:'u2',datum:'2026-02-19T23:02:00',rA:{u7:3,u5:5},rAdv:{u7:3},body:`Bij een tweetrapsmaking krijgt de eerste verkrijger het vermogen, en wat bij haar overlijden over is, gaat naar een tweede verkrijger. Het kan fiscaal voordelig zijn als de tweede verkrijging wordt belast ten opzichte van de oorspronkelijke erflater, maar dat hangt af van de situatie. Dit is echt notariswerk.
Leg vast dat je de wens hebt gesignaleerd en hebt doorverwezen.`}
  ]},
 {id:'vbf-038',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-02-20T11:05:00',views:195,tags:['erfbelasting','schenking','fictie'],beste:'vbf-038-a1',
  titel:'Schenkingen in de jaren voor overlijden en erfbelasting',
  body:`Een klant vraagt of schenkingen die zijn moeder twee jaar geleden deed nog meetellen voor de erfbelasting nu zij is overleden. Hoe zit het?`,
  antwoorden:[
   {id:'vbf-038-a1',auteur:'u2',datum:'2026-02-20T13:01:00',rA:{u8:4,u4:3,u3:4},rAdv:{},body:`Schenkingen die kort voor het overlijden zijn gedaan, kunnen voor de erfbelasting worden meegeteld. De wet kent daarvoor een termijn en de betaalde schenkbelasting wordt dan verrekend. Twee jaar is in de regel ruim buiten die termijn, maar controleer de feiten en de actuele regels.
Leg vast welke schenkingen je hebt gezien en wanneer ze zijn gedaan.`}
  ]},
 {id:'vbf-039',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-02-24T07:20:00',views:54,tags:['ORV','kruislings','erfbelasting'],beste:null,
  titel:'Kruislingse ORV en erfbelasting voor samenwoners',
  body:`Twee ongehuwde partners hebben elk een ORV op eigen leven. Wordt de uitkering belast met erfbelasting? Hoe richten jullie dit in?`,
  antwoorden:[
   {id:'vbf-039-a1',auteur:'u3',datum:'2026-02-25T02:43:00',rA:{u4:4},rAdv:{},body:`Bij een kruislingse ORV is de partner verzekeringnemer en begunstigde op het leven van de ander, en betaalt de partner de premie uit eigen middelen. Dan is de uitkering in de regel niet belast met erfbelasting.
- Controleer wie verzekeringnemer en begunstigde is.
- Leg vast van welke rekening de premie wordt betaald.
Gaat de premie van een gezamenlijke rekening, dan is de bewijslast lastiger.`},
   {id:'vbf-039-a2',auteur:'u5',datum:'2026-02-25T13:20:00',rA:{u4:5},rAdv:{},body:`Goed punt van de gezamenlijke rekening. Ik adviseer om de premie per partner te laten afschrijven van de eigen rekening. Dat voorkomt discussie na overlijden.`}
  ]},
 {id:'vbf-040',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-02-25T19:15:00',views:252,tags:['ouderlijke boedelverdeling','testament','oud testament'],beste:'vbf-040-a1',
  titel:'Oud testament met ouderlijke boedelverdeling: nog geldig',
  body:`Een klant heeft een testament uit de jaren tachtig met een ouderlijke boedelverdeling. Moet ik adviseren dat testament te laten herzien?`,
  antwoorden:[
   {id:'vbf-040-a1',auteur:'u5',datum:'2026-02-26T11:42:00',rA:{u2:4},rAdv:{},body:`Een oud testament kan nog geldig zijn, maar is soms niet meer in lijn met het huidige erfrecht en de huidige wensen. Bovendien zijn de fiscale gevolgen veranderd sinds de invoering van het nieuwe erfrecht.
- Adviseer een check bij de notaris.
- Leg vast dat je het hebt gesignaleerd.
Bespreek ook of de verdeling nog past bij de gezinssituatie.`}
  ]},
 {id:'vbf-041',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-02-26T12:35:00',views:317,tags:['erfenis','kinderen','hypotheek'],beste:'vbf-041-a1',
  titel:'Kind wil woning van overleden ouder overnemen met hypotheek',
  body:`Na overlijden van een ouder wil een van de kinderen de ouderlijke woning overnemen en de broers en zussen uitkopen. Hoe pakken jullie dit aan?`,
  antwoorden:[
   {id:'vbf-041-a1',auteur:'u1',datum:'2026-02-26T18:30:00',rA:{},rAdv:{},body:`Werkwijze die wij volgen:
- Laat de woning taxeren zodat de uitkoopsom voor alle erfgenamen helder is.
- Bekijk of het kind de uitkoopsom plus kosten kan financieren als normale aankoop.
- Leg de afspraken tussen erfgenamen schriftelijk vast via de notaris.
Controleer de voorwaarden van de geldverstrekker voor een overname uit een nalatenschap.`},
   {id:'vbf-041-a2',auteur:'u2',datum:'2026-02-26T23:19:00',rA:{u3:5},rAdv:{},body:`Let op de fiscale kant: het eigen erfdeel in de woning hoeft niet gefinancierd te worden, maar dat kan het bijleenregime en de eigenwoningschuld beïnvloeden. Laat dat goed doorrekenen. Leg in het dossier vast welk deel van de woning is geërfd en welk deel is gefinancierd.`},
   {id:'vbf-041-a3',auteur:'u5',datum:'2026-02-27T07:48:00',rA:{u4:5},rAdv:{u4:5},body:`In de praktijk zie ik ook dat de verdeling van de woning en de overige nalatenschap samen wordt geregeld. Maak dan een overzicht van wie wat krijgt en neem dat op in het dossier. Zo is later voor alle partijen terug te vinden waarop de financiering is gebaseerd.`}
  ]},
 {id:'vbf-042',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-02-27T18:05:00',views:122,tags:['erfenis','huwelijk','uitsluitingsclausule'],beste:'vbf-042-a1',
  titel:'Erfenis met uitsluitingsclausule in de gemeenschap van goederen',
  body:`Een getrouwde klant heeft geërfd met een uitsluitingsclausule. Ze willen het geld gebruiken om de gezamenlijke hypotheek af te lossen. Wat moeten ze weten?`,
  antwoorden:[
   {id:'vbf-042-a1',auteur:'u5',datum:'2026-02-28T07:34:00',rA:{},rAdv:{},body:`Door de uitsluitingsclausule valt de erfenis niet in de gemeenschap. Als het geld wordt gebruikt om een gezamenlijke schuld af te lossen, kan er een vergoedingsrecht ontstaan voor de erfgenaam. Dat is relevant bij scheiding of overlijden.
- Leg vast dat het om privévermogen gaat.
- Adviseer dit schriftelijk vast te leggen, eventueel bij de notaris.`}
  ]},
 {id:'vbf-043',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-03-01T20:30:00',views:592,tags:['executeur','afwikkeling','bank'],beste:null,
  titel:'Bankrekeningen geblokkeerd na overlijden: hypotheeklasten betalen',
  body:`Na overlijden van een klant staan de rekeningen geblokkeerd. De langstlevende vraagt hoe de maandlasten van de hypotheek worden betaald. Wat adviseren jullie?`,
  antwoorden:[
   {id:'vbf-043-a1',auteur:'u4',datum:'2026-03-02T10:02:00',rA:{},rAdv:{},body:`Neem zo snel mogelijk contact op met de geldverstrekker en meld het overlijden. Vaak is tijdelijk uitstel of een betaalafspraak mogelijk, maar controleer de voorwaarden van de geldverstrekker.
- Vraag een verklaring van erfrecht aan, die is nodig om rekeningen vrij te geven.
- Leg in het dossier vast wat er met de geldverstrekker is afgesproken.`},
   {id:'vbf-043-a2',auteur:'u3',datum:'2026-03-02T15:45:00',rA:{u4:5},rAdv:{u4:5},body:`Check ook of er een ORV of uitvaartverzekering loopt. Die uitkering kan snel worden aangevraagd en de eerste lasten overbruggen. Leg in het dossier vast welke polissen je hebt gecontroleerd en wat de verwachte uitkering is.`}
  ]},
 {id:'vbf-044',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-03-06T17:40:00',views:250,tags:['erfbelasting','vrijstelling','kinderen'],beste:null,
  titel:'Erfbelasting bij kinderen onder de 23',
  body:`Een klant met jonge kinderen vraagt of haar kinderen bij haar overlijden meer vrijstelling hebben. Ze wil weten of haar testament moet worden aangepast. Wat weten jullie?`,
  antwoorden:[
   {id:'vbf-044-a1',auteur:'u2',datum:'2026-03-07T09:40:00',rA:{u5:4,u7:5,u1:4},rAdv:{u7:4,u5:4},body:`Er is geen hogere vrijstelling op basis van leeftijd meer; die oude regeling voor jonge kinderen is lang geleden afgeschaft. Kinderen hebben één vaste vrijstelling. Alleen voor kinderen met een ziekte of beperking die niet in hun eigen onderhoud kunnen voorzien geldt een hogere vrijstelling. Controleer de actuele bedragen bij belastingdienst.nl.
Bij jonge kinderen gaat het testament vooral over andere zaken:
- Wie wordt voogd?
- Wie beheert het vermogen tot een bepaalde leeftijd (bewind)?
- Moet de wettelijke verdeling blijven of worden aangepast?
Combineer dit met de vraag of een ORV voldoende dekking geeft, zodat de woonlasten voor de achterblijvers betaalbaar blijven. Leg vast dat je de klant hebt verwezen naar een notaris en welke dekking je hebt besproken.`}
  ]},
 {id:'vbf-045',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-03-08T20:55:00',views:304,tags:['erfenis','box 3','peildatum'],beste:'vbf-045-a1',
  titel:'Erfenis verkregen in de loop van het jaar en box 3',
  body:`Een klant heeft in de zomer een erfenis ontvangen. Wanneer telt die mee in box 3?`,
  antwoorden:[
   {id:'vbf-045-a1',auteur:'u2',datum:'2026-03-09T03:25:00',rA:{},rAdv:{},body:`Box 3 kijkt naar de stand op 1 januari. Een erfenis die in de loop van het jaar wordt ontvangen, telt pas mee op 1 januari van het jaar erna. Wel belangrijk: het moment waarop de erfenis fiscaal tot het vermogen behoort, kan eerder liggen dan het moment van uitbetaling. Laat dit bij twijfel uitzoeken.
Leg in het dossier vast wanneer de erfenis is verkregen.`}
  ]},
 {id:'vbf-046',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-03-13T17:50:00',views:488,tags:['erfrecht','stiefkinderen','testament'],beste:'vbf-046-a1',
  titel:'Samengesteld gezin: stiefkinderen en de woning',
  body:`Een getrouwd stel heeft ieder kinderen uit een eerdere relatie. Ze willen dat de langstlevende in de woning kan blijven, maar dat uiteindelijk alle kinderen evenveel krijgen. Hoe adviseren jullie hierover?`,
  antwoorden:[
   {id:'vbf-046-a1',auteur:'u5',datum:'2026-03-14T00:40:00',rA:{u6:4,u8:5},rAdv:{u8:5},body:`Volgens de wet zijn stiefkinderen geen erfgenaam van de stiefouder. Wil het stel dat alle kinderen gelijk delen, dan is een testament nodig. Daarnaast is de vraag hoe de langstlevende de woning kan blijven bewonen zonder dat de kinderen van de overleden partner tekortkomen.
- Adviseer een notaris met ervaring in samengestelde gezinnen.
- Leg vast welke wensen het stel heeft.
Voor de erfbelasting kunnen stiefkinderen onder voorwaarden met eigen kinderen worden gelijkgesteld. Controleer de actuele regels.`},
   {id:'vbf-046-a2',auteur:'u2',datum:'2026-03-14T22:26:00',rA:{u1:3,u4:4,u8:4,u7:4},rAdv:{u1:3,u8:4},body:`Bekijk ook de ORV. Een ORV op het leven van de partner met de grootste inbreng kan de positie van de langstlevende versterken, zonder dat de kinderen tekortkomen. Leg vast welk scenario is gekozen en waarom, zodat de keuze later uitlegbaar is.`}
  ]},
 {id:'vbf-047',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-03-14T19:30:00',views:563,tags:['erfenis','aflossen','boete'],beste:null,
  titel:'Erfenis gebruiken om boetevrij af te lossen bij overlijden',
  body:`Na overlijden van een partner wil de langstlevende een deel van de hypotheek aflossen met de erfenis. Is er dan een boete verschuldigd?`,
  antwoorden:[
   {id:'vbf-047-a1',auteur:'u4',datum:'2026-03-15T04:43:00',rA:{u5:4,u2:5},rAdv:{},body:`Veel geldverstrekkers staan boetevrij aflossen toe bij overlijden van een schuldenaar, maar de voorwaarden en termijnen verschillen. Controleer de voorwaarden van de geldverstrekker.
- Leg in het dossier vast welke afkoop of aflossing is gedaan.
- Kijk ook of er een renteherziening gewenst is.`}
  ]},
 {id:'vbf-048',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-03-15T16:50:00',views:561,tags:['erfrecht','ouders','geen kinderen'],beste:'vbf-048-a1',
  titel:'Wie erft als er geen partner en geen kinderen zijn',
  body:`Een alleenstaande klant zonder kinderen vraagt wie haar woning erft als ze geen testament heeft. Ze wil weten of het naar haar ouders gaat.`,
  antwoorden:[
   {id:'vbf-048-a1',auteur:'u5',datum:'2026-03-16T12:29:00',rA:{},rAdv:{},body:`Zonder testament erven eerst de ouders en broers en zussen. De verdeling volgt de wettelijke regels. Als zij een andere wens heeft, bijvoorbeeld een goed doel of een vriend, dan is een testament nodig.
Leg in het dossier vast dat je de wens hebt besproken en hebt doorverwezen naar de notaris.`}
  ]},
 {id:'vbf-049',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-03-15T18:05:00',views:279,tags:['erfbelasting','goed doel','ANBI'],beste:null,
  titel:'Nalaten aan een goed doel en erfbelasting',
  body:`Een klant wil een deel van haar vermogen nalaten aan een goed doel. Moet het goede doel erfbelasting betalen?`,
  antwoorden:[
   {id:'vbf-049-a1',auteur:'u2',datum:'2026-03-16T02:00:00',rA:{u1:4},rAdv:{},body:`Een algemeen nut beogende instelling met de juiste status betaalt in de regel geen erfbelasting over een verkrijging. Controleer de ANBI-status van de instelling.
Leg vast welke instelling de klant noemt en verwijs voor het testament naar de notaris.`}
  ]},
 {id:'vbf-050',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-03-19T14:25:00',views:531,tags:['erfenis','scheiding','privévermogen'],beste:'vbf-050-a1',
  titel:'Erfenis gebruikt voor de woning en vervolgens scheiding',
  body:`Een klant heeft een paar jaar geleden een erfenis in de gezamenlijke woning gestoken. Ze gaan nu scheiden. Heeft zij recht op dat geld terug?`,
  antwoorden:[
   {id:'vbf-050-a1',auteur:'u5',datum:'2026-03-20T07:27:00',rA:{},rAdv:{},body:`Dat hangt af van het huwelijksvermogensregime en van of de erfenis met een uitsluitingsclausule is verkregen. Bij een huwelijk vanaf 2018 valt een erfenis in de regel buiten de gemeenschap. Bij privévermogen dat in een gezamenlijke woning is gestoken, kan een vergoedingsrecht ontstaan.
Laat de klant hierover advies inwinnen bij een advocaat of mediator.`},
   {id:'vbf-050-a2',auteur:'u8',datum:'2026-03-20T14:17:00',rA:{u2:4,u6:4,u7:5,u4:5},rAdv:{u2:4,u6:4,u7:5,u4:5},body:`Vastleggen in het dossier is hier belangrijk: noteer dat je geen juridisch advies geeft en hebt doorverwezen. Ook een korte notitie dat de klant de verwijzing heeft begrepen, helpt bij een latere klacht.`}
  ]},
 {id:'vbf-051',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-04-02T15:50:00',views:325,tags:['box 3','fiscaal partner','verdeling'],beste:null,
  titel:'Box 3 vermogen verdelen tussen fiscale partners',
  body:`Een stel is fiscaal partner. Het spaargeld staat grotendeels op naam van één partner. Maakt het voor box 3 uit op wiens naam het staat?`,
  antwoorden:[
   {id:'vbf-051-a1',auteur:'u2',datum:'2026-04-03T04:39:00',rA:{u1:3,u4:5,u5:5,u3:4},rAdv:{u1:3,u4:5,u5:5,u3:4},body:`Fiscale partners mogen de gezamenlijke grondslag in box 3 in de aangifte vrij verdelen. Op wiens naam het geld staat, is daarvoor niet bepalend. De heffingsvrije vermogens van beide partners worden benut.
Let op: voor het huwelijksvermogensrecht en voor toeslagen kan de verdeling wel uitmaken. Leg in het dossier vast hoe de klant de verdeling doet.`}
  ]},
 {id:'vbf-052',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-04-03T11:25:00',views:177,tags:['box 3','aflossen','spaargeld'],beste:'vbf-052-a1',
  titel:'Spaargeld in box 3 gebruiken om af te lossen: wat rekenen jullie door',
  body:`Een klant heeft flink spaargeld in box 3 en een aflossingsvrije hypotheek. Hij vraagt of aflossen verstandig is. Welke punten nemen jullie mee?`,
  antwoorden:[
   {id:'vbf-052-a1',auteur:'u2',datum:'2026-04-03T18:08:00',rA:{u6:5,u4:4,u8:5,u3:4},rAdv:{u4:4},body:`Wij rekenen het verschil door tussen de netto hypotheekrente en het netto rendement op het spaargeld na box 3-heffing. Daarnaast kijken we naar:
- de gewenste buffer en liquiditeit;
- boetevrije aflossingsruimte en eventuele boeterente;
- de gevolgen voor de renteaftrek en het eigenwoningforfait.
Leg de afweging en de gekozen buffer vast in het dossier. Gebruik de actuele box 3-percentages.`},
   {id:'vbf-052-a2',auteur:'u1',datum:'2026-04-04T15:08:00',rA:{},rAdv:{},body:`Bespreek ook of er later weer geleend moet worden, bijvoorbeeld voor een verbouwing. Afgelost geld krijg je niet altijd zomaar terug, en een nieuwe lening moet opnieuw voldoen aan de leennormen. Leg in het dossier vast welke mogelijkheden voor herfinanciering je hebt besproken.`},
   {id:'vbf-052-a3',auteur:'u7',datum:'2026-04-04T21:09:00',rA:{u8:5,u5:4,u3:5},rAdv:{u5:4,u3:5},body:`En kijk naar de pensioensituatie. Als het inkomen na pensionering daalt, kan een lagere hypotheek de betaalbaarheid verbeteren. Dat maakt aflossen soms juist zinvol.`}
  ]},
 {id:'vbf-053',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-04-09T19:50:00',views:353,tags:['box 3','tegenbewijs','werkelijk rendement'],beste:'vbf-053-a1',
  titel:'Tegenbewijsregeling box 3: wat vertellen jullie klanten',
  body:`Klanten vragen of ze minder box 3-belasting kunnen betalen als hun werkelijk rendement lager is dan het forfaitaire. Hoe gaan jullie daarmee om?`,
  antwoorden:[
   {id:'vbf-053-a1',auteur:'u2',datum:'2026-04-09T22:11:00',rA:{u5:4},rAdv:{u5:4},body:`Er is een tegenbewijsregeling waarmee een belastingplichtige kan aantonen dat het werkelijke rendement lager is dan het forfaitaire. Hoe het werkelijke rendement wordt berekend, staat in de regels; denk aan rente, dividend en waardeveranderingen.
- Wij verwijzen voor de uitwerking naar een fiscalist of de aangiftesoftware.
- Leg vast dat je het onderwerp hebt besproken, maar geen fiscaal advies hebt gegeven.
Volg de actuele ontwikkelingen, want de regels rond box 3 veranderen.`}
  ]},
 {id:'vbf-054',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-04-11T17:05:00',views:474,tags:['box 3','schulden','drempel'],beste:null,
  titel:'Box 3 schuld voor een tweede woning',
  body:`Een klant heeft een recreatiewoning met een lening. Hoe telt die lening mee in box 3?`,
  antwoorden:[
   {id:'vbf-054-a1',auteur:'u2',datum:'2026-04-12T03:43:00',rA:{u8:5,u3:4,u7:5,u4:5},rAdv:{u7:5},body:`Een recreatiewoning valt in box 3, en de bijbehorende lening is een box 3-schuld. Schulden worden in box 3 alleen in mindering gebracht voor zover ze boven de schuldendrempel uitkomen. Controleer het actuele drempelbedrag.
Leg in het dossier vast dat de rente niet aftrekbaar is in box 1.`}
  ]},
 {id:'vbf-055',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-04-15T17:05:00',views:359,tags:['box 3','groene beleggingen','vrijstelling'],beste:null,
  titel:'Groene beleggingen en box 3',
  body:`Een klant wil weten of groene beleggingen nog fiscaal interessant zijn. Wat zeggen jullie?`,
  antwoorden:[
   {id:'vbf-055-a1',auteur:'u2',datum:'2026-04-16T09:30:00',rA:{u5:4,u7:4,u1:3},rAdv:{u7:4,u5:4},body:`Het fiscale voordeel verdwijnt. De vrijstelling en heffingskorting voor groene beleggingen in box 3 worden afgebouwd en vervallen volgens de huidige plannen; er is nog discussie over het precieze jaartal. Controleer de actuele stand bij belastingdienst.nl.
Mijn advies aan klanten:
- Kies groene beleggingen op basis van rendement, risico en duurzaamheidswens, niet om het belastingvoordeel.
- Let op de looptijd en verhandelbaarheid van het product.
- Houd rekening met de geplande overgang naar een box 3-heffing op werkelijk rendement; dat verandert de afweging opnieuw.
Leg in het dossier vast dat het fiscale voordeel tijdelijk is en dat de klant bewust kiest. Gaat het om beleggingsadvies, check dan of je daarvoor de juiste vergunning hebt.`}
  ]},
 {id:'vbf-056',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-04-17T09:35:00',views:98,tags:['box 3','kinderen','minderjarig'],beste:null,
  titel:'Box 3 vermogen van minderjarige kinderen',
  body:`Ouders hebben een spaarrekening op naam van hun minderjarige kind. Bij wie telt dat geld mee in box 3?`,
  antwoorden:[
   {id:'vbf-056-a1',auteur:'u2',datum:'2026-04-17T22:02:00',rA:{u6:4},rAdv:{},body:`Het vermogen van een minderjarig kind wordt in box 3 in de regel toegerekend aan de ouder die het gezag heeft. Bij gezamenlijk gezag wordt het verdeeld. Dat geldt niet voor vermogen waarvan het genot niet aan de ouders toekomt, bijvoorbeeld bij een uitsluiting van het ouderlijk vruchtgenot.
Leg vast hoe de rekening is ingericht en verwijs bij twijfel naar een fiscalist.`}
  ]},
 {id:'vbf-057',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-04-17T12:00:00',views:225,tags:['fiscaal partner','samenlevingscontract','ongehuwd'],beste:'vbf-057-a1',
  titel:'Wanneer zijn ongehuwd samenwonenden fiscaal partner',
  body:`Een ongehuwd stel koopt samen een woning. Zijn zij dan automatisch fiscaal partner?`,
  antwoorden:[
   {id:'vbf-057-a1',auteur:'u2',datum:'2026-04-17T17:57:00',rA:{},rAdv:{},body:`Samen een woning kopen met beide inschrijving op hetzelfde adres kan leiden tot fiscaal partnerschap. Ook een notarieel samenlevingscontract of een gezamenlijk kind zijn criteria. Controleer de actuele criteria bij de Belastingdienst.
- Leg vast op welke grond je fiscaal partnerschap aanneemt.
- Bespreek wat dit betekent voor de verdeling van de renteaftrek en box 3.`}
  ]},
 {id:'vbf-058',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-04-19T14:55:00',views:294,tags:['partners','renteaftrek','verdeling'],beste:'vbf-058-a1',
  titel:'Renteaftrek verdelen bij fiscale partners met ongelijk inkomen',
  body:`Een stel heeft een sterk ongelijk inkomen. Wie trekt de hypotheekrente af en maakt het uit?`,
  antwoorden:[
   {id:'vbf-058-a1',auteur:'u1',datum:'2026-04-20T03:14:00',rA:{u4:5,u7:4},rAdv:{},body:`Fiscale partners mogen het saldo van de eigen woning in de aangifte vrij verdelen. Omdat de aftrek in de regel beperkt is tot een maximaal tarief, is het verschil minder groot dan vroeger, maar het kan nog uitmaken voor heffingskortingen.
Leg in het dossier vast welke verdeling je in de berekening hebt aangenomen.`}
  ]},
 {id:'vbf-059',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-04-25T15:35:00',views:407,tags:['huwelijkse voorwaarden','woning','ondernemer'],beste:'vbf-059-a1',
  titel:'Huwelijkse voorwaarden voor ondernemer bij aankoop woning',
  body:`Een ondernemer gaat trouwen en wil de woning beschermen tegen zakelijke schulden. Huwelijkse voorwaarden zijn in de maak. Wat bespreken jullie vanuit hypotheekperspectief?`,
  antwoorden:[
   {id:'vbf-059-a1',auteur:'u5',datum:'2026-04-26T05:39:00',rA:{u2:5,u8:4},rAdv:{u8:4},body:`Wij bespreken op naam van wie de woning komt en hoe de hypotheek wordt verdeeld. Bij koude uitsluiting kunnen andere afspraken gelden dan bij een finaal verrekenbeding.
- Leg vast wie eigenaar wordt en in welke verhouding.
- Stem af met de notaris over de huwelijkse voorwaarden.
- Controleer de voorwaarden van de geldverstrekker over beide partners als schuldenaar.
De bescherming is niet absoluut; laat dit juridisch toetsen.`},
   {id:'vbf-059-a2',auteur:'u2',datum:'2026-04-27T01:12:00',rA:{},rAdv:{},body:`Let ook op de financiering van de inbreng. Als de ene partner meer inbrengt, leg dat vast om later discussie te voorkomen. Zet de gemaakte afspraken over de inbreng ook in het adviesrapport.`}
  ]},
 {id:'vbf-060',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-04-28T17:20:00',views:290,tags:['scheiding','eigen woning','renteaftrek'],beste:'vbf-060-a1',
  titel:'Renteaftrek na scheiding voor de vertrekkende partner',
  body:`Na een scheiding blijft een partner in de woning en de ander vertrekt. Kan de vertrekkende partner nog rente aftrekken?`,
  antwoorden:[
   {id:'vbf-060-a1',auteur:'u2',datum:'2026-04-29T08:40:00',rA:{u7:5},rAdv:{},body:`Er is een tijdelijke regeling waarbij de woning voor de vertrekkende partner nog als eigen woning kan gelden, mits de ex-partner er blijft wonen. Die regeling is beperkt in duur. Controleer de actuele voorwaarden.
Leg in het dossier vast wanneer de vertrekkende partner is verhuisd.`},
   {id:'vbf-060-a2',auteur:'u4',datum:'2026-04-29T23:58:00',rA:{},rAdv:{},body:`Bespreek ook het ontslag uit de hoofdelijke aansprakelijkheid. Dat is een apart traject bij de geldverstrekker met eigen voorwaarden. Leg in het dossier vast of en wanneer het ontslag is aangevraagd.`}
  ]},
 {id:'vbf-061',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-05-01T20:40:00',views:60,tags:['huwelijk','gemeenschap van goederen','beperkt'],beste:null,
  titel:'Beperkte gemeenschap van goederen: wat valt erbuiten',
  body:`Klanten gaan trouwen. Ze vragen wat er met hun eigen spaargeld van voor het huwelijk gebeurt. Wat leggen jullie uit?`,
  antwoorden:[
   {id:'vbf-061-a1',auteur:'u5',datum:'2026-05-02T00:42:00',rA:{},rAdv:{},body:`Bij huwelijken gesloten vanaf 1 januari 2018 geldt in de regel een beperkte gemeenschap van goederen. Vermogen van voor het huwelijk en erfenissen en schenkingen blijven privé. Wat samen tijdens het huwelijk wordt opgebouwd, valt in de gemeenschap.
Wil het stel iets anders, dan zijn huwelijkse voorwaarden nodig. Leg vast dat je dit hebt besproken.`}
  ]},
 {id:'vbf-062',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-05-08T14:25:00',views:569,tags:['partnerpensioen','nabestaanden','ORV'],beste:'vbf-062-a1',
  titel:'Nabestaandenpensioen en ORV bij ongehuwde partners',
  body:`Een ongehuwde partner is niet aangemeld bij het pensioenfonds. Moet ik de ORV daarom hoger adviseren?`,
  antwoorden:[
   {id:'vbf-062-a1',auteur:'u7',datum:'2026-05-08T17:27:00',rA:{u2:4},rAdv:{},body:`Bij ongehuwde partners is aanmelding bij het pensioenfonds vaak nodig om recht te hebben op partnerpensioen. Controleer de pensioenregeling.
- Adviseer de klant de partner aan te melden.
- Bereken de ORV op basis van de situatie met en zonder partnerpensioen.
- Leg in het dossier vast welke uitgangspunten je hebt gebruikt.`},
   {id:'vbf-062-a2',auteur:'u3',datum:'2026-05-08T23:32:00',rA:{u6:4,u1:5},rAdv:{},body:`Een te hoge ORV is niet nodig, maar een te lage is pijnlijk. Ik reken altijd beide scenario's door en bespreek ze. Leg beide berekeningen en de gekozen dekking vast in het dossier.`}
  ]},
 {id:'vbf-063',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-05-10T12:20:00',views:53,tags:['box 3','vordering','ouders'],beste:'vbf-063-a1',
  titel:'Lening aan kind in box 3 bij ouders',
  body:`Ouders lenen geld aan hun kind voor een woning. Hoe telt die vordering mee in box 3 voor de ouders?`,
  antwoorden:[
   {id:'vbf-063-a1',auteur:'u2',datum:'2026-05-10T18:41:00',rA:{u3:4},rAdv:{},body:`De vordering op het kind is een bezitting van de ouders in box 3. De ontvangen rente is onderdeel van hun vermogen, maar box 3 werkt met een forfaitair of op tegenbewijs gebaseerd rendement. Controleer de actuele box 3-regels voor vorderingen.
Leg vast welke rente is afgesproken en dat die zakelijk is.`},
   {id:'vbf-063-a2',auteur:'u5',datum:'2026-05-10T21:44:00',rA:{},rAdv:{},body:`Voor het kind: als het een eigenwoningschuld is, moet de lening aan de voorwaarden voldoen, zoals een annuïtaire of lineaire aflossing. En het kind moet de gegevens van de lening opgeven in de aangifte.`}
  ]},
 {id:'vbf-064',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-05-11T15:10:00',views:112,tags:['partners','scheiding','box 3'],beste:null,
  titel:'Box 3 in het jaar van scheiding',
  body:`Een stel scheidt in de loop van het jaar. Kunnen ze over dat jaar box 3 nog verdelen?`,
  antwoorden:[
   {id:'vbf-064-a1',auteur:'u2',datum:'2026-05-11T22:32:00',rA:{},rAdv:{},body:`Fiscaal partnerschap kan voor het hele jaar gelden als ze een deel van het jaar partner waren en daarvoor kiezen. Dan kan de verdeling nog flexibel. De regels zijn wat technisch; laat de aangifte bij twijfel door een fiscalist doen.
Leg vast welke datum van scheiding is gehanteerd.`}
  ]},
 {id:'vbf-065',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-05-12T21:40:00',views:367,tags:['partners','eigen inbreng','vergoedingsrecht'],beste:'vbf-065-a1',
  titel:'Ongelijke inbreng bij aankoop door ongehuwde partners',
  body:`Eén partner brengt veel eigen geld in bij de aankoop, de ander niet. Ze worden ieder voor de helft eigenaar. Hoe leggen jullie dat vast?`,
  antwoorden:[
   {id:'vbf-065-a1',auteur:'u5',datum:'2026-05-13T11:43:00',rA:{u3:4},rAdv:{},body:`De inbreng kan worden vastgelegd in een samenlevingscontract, in de leveringsakte of in een aparte overeenkomst. Zonder vastlegging kan er later discussie ontstaan of de inbreng een schenking was.
- Leg in het dossier vast wie wat inbrengt.
- Adviseer de afspraken bij de notaris vast te leggen.
Bespreek ook de fiscale gevolgen, zoals de eigenwoningschuld per partner.`},
   {id:'vbf-065-a2',auteur:'u1',datum:'2026-05-14T10:41:00',rA:{u4:4,u3:4,u8:5,u7:5},rAdv:{u8:5},body:`Ik zie vaak dat partners ervoor kiezen ongelijk eigenaar te worden, bijvoorbeeld zestig-veertig. Dat kan, maar dan moet de hypotheek ook passen bij die verdeling. Controleer de voorwaarden van de geldverstrekker.`}
  ]},
 {id:'vbf-066',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-05-13T07:05:00',views:156,tags:['box 3','beleggingen','hypotheek'],beste:null,
  titel:'Beleggingen aanhouden of aflossen bij renteherziening',
  body:`Bij een renteherziening wil een klant zijn beleggingen in box 3 gebruiken om af te lossen. De beleggingen staan nu op winst. Wat zijn de overwegingen?`,
  antwoorden:[
   {id:'vbf-066-a1',auteur:'u2',datum:'2026-05-14T09:10:00',rA:{u5:5,u1:4,u7:4},rAdv:{u5:4,u1:4},body:`In het huidige box 3-stelsel wordt de koerswinst niet apart belast bij verkoop; box 3 kijkt naar de waarde op de peildatum. Verkopen om af te lossen is dus niet direct belast. Wel kunnen de plannen voor werkelijk rendement dat in de toekomst anders maken; controleer de actuele stand.
Overwegingen:
- Vergelijk de nieuwe hypotheekrente (na aftrek) met het verwachte netto rendement van de beleggingen.
- Houd een buffer aan; afgeloste hypotheek is niet zomaar terug te lenen.
- Check de boetevrije aflossingsruimte. Bij renteherziening is aflossen meestal boetevrij, maar controleer de voorwaarden.
- Bespreek het risicoprofiel van de klant en de spreiding van zijn vermogen.
Gebruik extra-aflossen.html voor de berekening. Leg vast welke scenario's je hebt vergeleken en waarom de klant kiest.`}
  ]},
 {id:'vbf-067',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-05-26T11:15:00',views:202,tags:['partners','pensioenverklaring','samenlevingscontract'],beste:'vbf-067-a1',
  titel:'Samenlevingscontract met of zonder notaris',
  body:`Klanten hebben een zelfgeschreven samenlevingscontract. Is dat voldoende voor fiscaal partnerschap en voor de partnervrijstelling?`,
  antwoorden:[
   {id:'vbf-067-a1',auteur:'u5',datum:'2026-05-26T19:06:00',rA:{},rAdv:{},body:`Voor fiscaal partnerschap en voor de partnervrijstelling in de erfbelasting is vaak een notarieel samenlevingscontract vereist. Een zelfgeschreven contract is meestal onvoldoende. Ook pensioenfondsen kunnen een notarieel contract vereisen.
Adviseer de klanten om het contract door een notaris te laten opstellen en leg dat vast in het dossier.`},
   {id:'vbf-067-a2',auteur:'u7',datum:'2026-05-27T02:17:00',rA:{u2:5,u4:5},rAdv:{u2:5},body:`Bij pensioenfondsen zie ik dat de eisen verschillen. Controleer de voorwaarden van de pensioenregeling. Vraag bij twijfel de pensioenuitvoerder welke eisen gelden en leg het antwoord vast in het dossier.`}
  ]},
 {id:'vbf-068',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-05-30T07:05:00',views:264,tags:['box 3','scheiding','woning'],beste:'vbf-068-a1',
  titel:'Ex-partner blijft mede-eigenaar: valt het aandeel in box 3',
  body:`Na een scheiding blijft een ex-partner mede-eigenaar van de woning waarin de ander woont. Valt dat aandeel na verloop van tijd in box 3?`,
  antwoorden:[
   {id:'vbf-068-a1',auteur:'u2',datum:'2026-05-30T22:53:00',rA:{u5:4},rAdv:{u5:4},body:`Na afloop van de tijdelijke regeling is de woning voor de vertrekkende partner geen eigen woning meer. Het aandeel en de bijbehorende schuld vallen dan in box 3. Controleer de actuele regels.
Leg vast welke afspraken de ex-partners hebben gemaakt over verkoop of overname.`}
  ]},
 {id:'vbf-069',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-06-05T17:00:00',views:509,tags:['partners','overlijden','hypotheek'],beste:null,
  titel:'Langstlevende wil hypotheek op eigen naam: wat controleren jullie',
  body:`Na overlijden van een partner wil de langstlevende de hypotheek op eigen naam voortzetten. Welke stappen doorlopen jullie?`,
  antwoorden:[
   {id:'vbf-069-a1',auteur:'u4',datum:'2026-06-05T21:48:00',rA:{u5:4,u1:5},rAdv:{u5:4,u1:5},body:`Wij doorlopen deze stappen:
- Melden van het overlijden bij de geldverstrekker.
- Controleren of de hypotheek op naam van de langstlevende kan worden voortgezet.
- Een nieuwe inkomensberekening op basis van het inkomen na overlijden.
Controleer de voorwaarden van de geldverstrekker, want die verschillen. Leg alle stappen vast in het dossier.`},
   {id:'vbf-069-a2',auteur:'u7',datum:'2026-06-06T09:05:00',rA:{u4:5,u2:5,u6:5,u1:5},rAdv:{u2:5},body:`Neem in de inkomensberekening het nabestaandenpensioen en eventuele Anw-uitkering mee. Let op: een Anw-uitkering is inkomensafhankelijk en eindigt bij AOW-leeftijd.`}
  ]},
 {id:'vbf-070',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-06-09T17:10:00',views:315,tags:['fiscaal partner','eigen woning','verhuizing'],beste:'vbf-070-a1',
  titel:'Partner woont nog niet in de woning: renteaftrek',
  body:`Een stel koopt een woning, maar één partner blijft voorlopig in de oude huurwoning. Kan die partner al rente aftrekken?`,
  antwoorden:[
   {id:'vbf-070-a1',auteur:'u2',datum:'2026-06-10T00:36:00',rA:{u6:4,u4:4,u8:5,u1:5},rAdv:{},body:`Voor de eigenwoningregeling moet de woning het hoofdverblijf zijn. Er zijn regels voor een woning die nog niet wordt bewoond, maar die zijn tijdelijk en voorwaardelijk. Bij fiscale partners kan het hoofdverblijf van de ene partner gevolgen hebben voor de andere. Controleer de actuele voorwaarden.
Leg vast wanneer beide partners in de woning gaan wonen.`}
  ]},
 {id:'vbf-071',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-06-13T16:05:00',views:469,tags:['box 3','ORV','kapitaalverzekering'],beste:null,
  titel:'ORV en box 3: moet die worden aangegeven',
  body:`Een klant vraagt of zijn ORV in box 3 moet worden opgegeven. Wat is gebruikelijk?`,
  antwoorden:[
   {id:'vbf-071-a1',auteur:'u3',datum:'2026-06-14T06:03:00',rA:{u5:3,u2:4,u4:4},rAdv:{u5:3,u4:4},body:`Een pure overlijdensrisicoverzekering heeft meestal geen of een zeer beperkte waarde in het economisch verkeer. Of en hoe die in box 3 moet worden opgenomen, hangt af van de regels. Controleer de actuele regels of vraag de verzekeraar om een opgave van de waarde.
Leg vast welke verzekering het betreft.`}
  ]},
 {id:'vbf-072',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-06-13T13:35:00',views:528,tags:['partners','toeslagen','vermogen'],beste:'vbf-072-a1',
  titel:'Schenking aan kind en toeslagen van partners',
  body:`Een stel ontvangt huurtoeslag en krijgt een schenking van ouders. Hoe beïnvloedt dat de toeslag?`,
  antwoorden:[
   {id:'vbf-072-a1',auteur:'u2',datum:'2026-06-14T01:05:00',rA:{u3:3,u7:4},rAdv:{},body:`Toeslagen kennen een vermogenstoets. Een schenking kan ervoor zorgen dat het vermogen op de peildatum boven de grens uitkomt. Controleer de actuele vermogensgrenzen.
Leg in het dossier vast dat je dit risico hebt besproken.`}
  ]},
 {id:'vbf-073',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-06-19T16:55:00',views:126,tags:['scheiding','ORV','begunstiging'],beste:null,
  titel:'ORV na scheiding: begunstiging aanpassen',
  body:`Na een scheiding staat de ex-partner nog als begunstigde op de ORV. Wat adviseren jullie?`,
  antwoorden:[
   {id:'vbf-073-a1',auteur:'u3',datum:'2026-06-20T07:08:00',rA:{u7:4,u5:3},rAdv:{u7:4,u5:3},body:`Bespreek de begunstiging direct. Als er afspraken zijn over het blijven betalen van de hypotheek, kan het juist gewenst zijn dat de ex-partner begunstigde blijft. In andere gevallen moet de begunstiging worden aangepast.
Leg de keuze vast in het dossier en vraag de verzekeraar om bevestiging.`}
  ]},
 {id:'vbf-074',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-06-24T16:15:00',views:270,tags:['partners','pensioenverklaring','hypotheek'],beste:'vbf-074-a1',
  titel:'Pensioen verevenen na scheiding en de hypotheekberekening',
  body:`Na een scheiding wordt het pensioen verevend. Hoe nemen jullie dat mee in de hypotheekberekening?`,
  antwoorden:[
   {id:'vbf-074-a1',auteur:'u7',datum:'2026-06-25T00:49:00',rA:{u3:3,u5:3,u1:5},rAdv:{u5:3},body:`Bij verevening krijgt de ex-partner een deel van het ouderdomspensioen. Dat verlaagt het toekomstige pensioeninkomen van de deelnemer.
- Vraag een actueel pensioenoverzicht op, bij voorkeur na verwerking van de verevening.
- Neem het verlaagde pensioen mee in de toetsing op betaalbaarheid na pensionering.
Controleer de voorwaarden van de geldverstrekker voor het meenemen van pensioeninkomen.`},
   {id:'vbf-074-a2',auteur:'u1',datum:'2026-06-25T06:28:00',rA:{u5:4,u7:5},rAdv:{u5:4,u7:5},body:`Ook goed om vast te leggen: wanneer de verevening is aangemeld. Soms is die nog niet verwerkt in het overzicht.`}
  ]},
 {id:'vbf-075',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-06-26T10:55:00',views:105,tags:['box 3','vruchtgebruik','bloot eigendom'],beste:null,
  titel:'Vruchtgebruik en bloot eigendom in box 3',
  body:`Een klant heeft het vruchtgebruik van een beleggingsportefeuille gekregen uit een nalatenschap; zijn kinderen hebben het bloot eigendom. Bij wie valt het in box 3?`,
  antwoorden:[
   {id:'vbf-075-a1',auteur:'u2',datum:'2026-06-27T09:45:00',rA:{u5:4,u7:4,u1:4},rAdv:{u5:4,u7:5},body:`Dat hangt af van het soort vruchtgebruik. Bij vruchtgebruik dat voortvloeit uit het erfrecht, zoals een wettelijk vruchtgebruik of een testamentair vruchtgebruik voor de partner, wordt het volledige vermogen voor box 3 bij de vruchtgebruiker meegeteld. De bloot eigenaren geven dan niets aan.
Bij ander vruchtgebruik geeft de vruchtgebruiker de waarde van het vruchtgebruik aan en de bloot eigenaar de waarde van het bloot eigendom. Die waarden bereken je met de tabellen van de Belastingdienst.
Praktisch:
- Vraag het testament of de verklaring van erfrecht op om het soort vruchtgebruik vast te stellen.
- Stem de aangifte af met de kinderen, zodat het vermogen niet dubbel of helemaal niet wordt aangegeven.
Leg vast welke bron je hebt gebruikt. Gaat het om een afwijkende constructie, laat het dan door een fiscalist bevestigen.`}
  ]},
 {id:'vbf-076',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-07-04T13:30:00',views:135,tags:['estate planning','woning','verkoop aan kind'],beste:'vbf-076-a1',
  titel:'Ouders verkopen woning aan kind: waar letten jullie op',
  body:`Ouders willen hun woning aan een van hun kinderen verkopen en zelf kleiner gaan wonen. Het kind financiert met een hypotheek. Welke punten bespreken jullie?`,
  antwoorden:[
   {id:'vbf-076-a1',auteur:'u5',datum:'2026-07-05T05:11:00',rA:{u4:3,u3:4,u7:4,u6:4},rAdv:{},body:`Belangrijkste punten:
- Laat de woning taxeren, zodat de koopprijs zakelijk is. Een te lage prijs kan als schenking worden gezien.
- Bespreek of de ouders een deel van de koopsom willen schuldig blijven of schenken.
- Controleer de gevolgen voor de overdrachtsbelasting en de actuele voorwaarden.
- Bespreek de gelijke behandeling van de andere kinderen.
Leg alle afspraken vast in het dossier en adviseer begeleiding door de notaris.`},
   {id:'vbf-076-a2',auteur:'u1',datum:'2026-07-05T06:05:00',rA:{u4:5,u6:5,u8:4},rAdv:{u4:5,u8:4},body:`Voor de financiering van het kind: controleer de voorwaarden van de geldverstrekker bij een aankoop van familie. Sommige vragen extra onderbouwing van de koopprijs.`}
  ]},
 {id:'vbf-077',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-07-05T14:35:00',views:383,tags:['estate planning','schuldigerkenning','woning'],beste:null,
  titel:'Koopsom deels schuldig blijven aan ouders',
  body:`Bij een verkoop van een woning aan een kind willen de ouders een deel van de koopsom schuldig blijven. Hoe richten jullie dat in?`,
  antwoorden:[
   {id:'vbf-077-a1',auteur:'u2',datum:'2026-07-05T17:08:00',rA:{u3:3,u6:3,u1:3,u7:4},rAdv:{u1:3,u7:4},body:`Leg de lening vast in een schriftelijke overeenkomst met een zakelijke rente en een aflossingsschema. Als het kind de lening als eigenwoningschuld wil aftrekken, moet die voldoen aan de voorwaarden, zoals aflossing binnen de wettelijke termijn.
- Leg de rente en aflossing vast in de overeenkomst.
- Het kind geeft de lening op in de aangifte.
- Bespreek of de ouders jaarlijks een deel willen kwijtschelden als schenking.
Laat de notaris dit bij de levering meenemen.`},
   {id:'vbf-077-a2',auteur:'u5',datum:'2026-07-06T04:24:00',rA:{u4:3},rAdv:{u4:3},body:`Controleer of de geldverstrekker van de eerste hypotheek akkoord is met een lening van de ouders. Sommige vragen een achterstellingsverklaring. Leg in het dossier vast of een achterstellingsverklaring nodig is en of die is aangeleverd.`}
  ]},
 {id:'vbf-078',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-07-08T17:15:00',views:22,tags:['levenstestament','woning','volmacht'],beste:'vbf-078-a1',
  titel:'Levenstestament en verkoop van de woning bij dementie',
  body:`Een oudere klant met beginnende geheugenproblemen heeft geen levenstestament. De kinderen vragen wat er gebeurt als de woning verkocht moet worden. Wat adviseren jullie?`,
  antwoorden:[
   {id:'vbf-078-a1',auteur:'u5',datum:'2026-07-09T01:34:00',rA:{},rAdv:{},body:`Zonder levenstestament kan, als de klant wilsonbekwaam wordt, een bewindvoerder of mentor nodig zijn, met toestemming van de kantonrechter voor verkoop van de woning. Een levenstestament kan zolang de klant nog wilsbekwaam is.
- Adviseer zo snel mogelijk naar de notaris te gaan.
- Leg vast dat je dit hebt besproken.
De notaris toetst de wilsbekwaamheid.`}
  ]},
 {id:'vbf-079',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-07-15T13:25:00',views:349,tags:['estate planning','vruchtgebruik','schenking'],beste:'vbf-079-a1',
  titel:'Woning schenken aan kinderen en blijven wonen',
  body:`Ouders willen hun woning aan de kinderen schenken om erfbelasting te besparen, maar willen er blijven wonen. Is dat zinvol?`,
  antwoorden:[
   {id:'vbf-079-a1',auteur:'u2',datum:'2026-07-16T04:13:00',rA:{u7:3,u5:5},rAdv:{},body:`Dit is fiscaal complex. Als ouders de woning schenken en er blijven wonen, kan de waarde bij overlijden toch weer bij de nalatenschap worden betrokken. Ook zijn er schenkbelasting en overdrachtsbelasting. Daarnaast verliezen de ouders de zeggenschap.
- Laat een fiscalist of notaris de verschillende scenario's doorrekenen.
- Leg vast dat je de risico's hebt besproken.
Vaak is een geleidelijke aanpak via schenken op papier of jaarlijks schenken beter in te passen.`}
  ]},
 {id:'vbf-080',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-07-18T11:45:00',views:63,tags:['estate planning','overwaarde','oudere klant'],beste:'vbf-080-a1',
  titel:'Overwaarde inzetten om te schenken aan kinderen',
  body:`Een gepensioneerd stel heeft veel overwaarde. Ze willen de kinderen nu al helpen. Wat zijn de opties?`,
  antwoorden:[
   {id:'vbf-080-a1',auteur:'u5',datum:'2026-07-19T07:08:00',rA:{u7:4},rAdv:{u7:4},body:`Opties die wij bespreken:
- een verzilverhypotheek of opeethypotheek, als de geldverstrekker die aanbiedt;
- een verhoging van de hypotheek met box 3-lening;
- schenken op papier, zodat geen liquiditeit nodig is.
Controleer de voorwaarden van de geldverstrekker en de betaalbaarheid na pensionering. Leg de doelen en de risico's vast in het dossier.`},
   {id:'vbf-080-a2',auteur:'u7',datum:'2026-07-20T02:19:00',rA:{},rAdv:{},body:`Let op de AOW en pensioeninkomsten. Bij een verhoging moet de hypotheek betaalbaar zijn op basis van het pensioeninkomen. Maak een overzicht van alle inkomsten.`}
  ]},
 {id:'vbf-081',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-07-18T15:00:00',views:52,tags:['estate planning','verhuur','box 3'],beste:null,
  titel:'Woning verhuren aan kind: waardering in box 3',
  body:`Ouders hebben een woning gekocht en verhuren die aan hun kind. Hoe wordt de woning gewaardeerd in box 3?`,
  antwoorden:[
   {id:'vbf-081-a1',auteur:'u2',datum:'2026-07-18T21:54:00',rA:{},rAdv:{},body:`Voor verhuurde woningen kan de leegwaarderatio worden toegepast, waardoor de waarde lager is dan de WOZ-waarde. Bij verhuur aan familie gelden beperkingen, bijvoorbeeld als de huur niet zakelijk is. Controleer de actuele regels.
Leg vast welke huur wordt betaald en hoe die is vastgesteld.`}
  ]},
 {id:'vbf-082',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-07-25T19:55:00',views:590,tags:['estate planning','woning','tweede woning'],beste:'vbf-082-a1',
  titel:'Tweede woning aankopen voor kind als belegging',
  body:`Ouders willen een appartement kopen voor hun studerende kind. Ze vragen of ze het appartement zelf moeten kopen of het geld moeten lenen aan het kind. Wat zijn de afwegingen?`,
  antwoorden:[
   {id:'vbf-082-a1',auteur:'u2',datum:'2026-07-26T10:17:00',rA:{u8:5},rAdv:{u8:5},body:`Bij aankoop door de ouders valt het appartement in hun box 3 en blijven zij eigenaar. Bij een lening aan het kind wordt het kind eigenaar en kan de lening mogelijk als eigenwoningschuld gelden. Ook schenking en overdrachtsbelasting spelen mee.
Laat de scenario's doorrekenen en leg vast welke keuze de klant maakt.`}
  ]},
 {id:'vbf-083',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-07-26T07:30:00',views:532,tags:['estate planning','huwelijkse voorwaarden','langstlevende'],beste:'vbf-083-a1',
  titel:'Langstlevende beschermen bij huwelijkse voorwaarden zonder verrekening',
  body:`Een stel is getrouwd met koude uitsluiting. De woning staat op naam van één partner. Hoe beschermen we de ander bij overlijden?`,
  antwoorden:[
   {id:'vbf-083-a1',auteur:'u5',datum:'2026-07-26T23:43:00',rA:{u3:3,u1:5,u2:5},rAdv:{u3:3,u1:5},body:`Bij koude uitsluiting heeft de partner zonder eigendom geen automatisch recht op de woning. Een testament met bijvoorbeeld een vruchtgebruik of legaat kan helpen.
- Adviseer een testament en eventueel een ORV.
- Leg vast dat je dit hebt besproken.`}
  ]},
 {id:'vbf-084',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-07-31T11:20:00',views:368,tags:['erfbelasting','planning','testament'],beste:null,
  titel:'Testament met legaat voor kleinkinderen',
  body:`Een klant wil een legaat aan haar kleinkinderen nalaten om de erfbelasting te spreiden. Is dat gebruikelijk?`,
  antwoorden:[
   {id:'vbf-084-a1',auteur:'u2',datum:'2026-08-01T09:35:00',rA:{u5:4,u7:4,u1:4},rAdv:{u5:4,u7:4},body:`Ja, dat is gebruikelijk. Door meer verkrijgers te laten erven, benut je extra vrijstellingen en blijft een groter deel in de lagere tariefschijf. Let wel op: voor kleinkinderen gelden een lagere vrijstelling dan voor kinderen en een hoger tarief. Controleer de actuele bedragen bij belastingdienst.nl.
Bespreek met de klant:
- Moet het legaat direct opeisbaar zijn, of pas later (bijvoorbeeld op een bepaalde leeftijd)?
- Bewind of beheer voor minderjarige kleinkinderen, en uitsluiting van ouderlijk vruchtgenot.
- Een uitsluitingsclausule, zodat het geld niet in een gemeenschap van goederen valt.
- Of het legaat in geld is en voldoende liquiditeit in de nalatenschap aanwezig is, bijvoorbeeld als de woning het grootste bezit is.
Het testament wordt door de notaris opgesteld. Leg in je dossier vast dat je de klant hebt verwezen en wat er is besproken.`}
  ]},
 {id:'vbf-085',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-08-02T09:40:00',views:570,tags:['schenking','woning','lening'],beste:'vbf-085-a1',
  titel:'Hypotheek verlagen met jaarlijkse schenkingen: hoe vastleggen',
  body:`Ouders willen jaarlijks schenken om de hypotheek van hun kind af te lossen. Hoe leggen jullie dat vast?`,
  antwoorden:[
   {id:'vbf-085-a1',auteur:'u1',datum:'2026-08-02T12:35:00',rA:{u4:5,u7:4,u6:3},rAdv:{u7:4,u6:3},body:`Schenking per jaar vastleggen:
- schriftelijke schenkingsovereenkomst of bankafschrift;
- vermelding van het bedrag en de datum;
- doel van de schenking, bijvoorbeeld aflossen.
Controleer de boetevrije aflossingsruimte bij de geldverstrekker.`}
  ]},
 {id:'vbf-086',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-08-14T08:50:00',views:563,tags:['estate planning','hypotheek','overlijden'],beste:null,
  titel:'Hypotheek na overlijden van beide ouders: wie betaalt',
  body:`Beide ouders zijn overleden en de woning heeft nog een hypotheek. De kinderen willen de woning verkopen. Moeten ze tot de verkoop de maandlasten betalen?`,
  antwoorden:[
   {id:'vbf-086-a1',auteur:'u4',datum:'2026-08-14T18:48:00',rA:{u7:3,u6:5,u5:3},rAdv:{},body:`De schuld is onderdeel van de nalatenschap. De maandlasten moeten in de regel worden doorbetaald uit de nalatenschap. Neem contact op met de geldverstrekker voor eventuele afspraken.
Leg in het dossier vast welke afspraken zijn gemaakt.`}
  ]},
 {id:'vbf-087',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-08-15T21:55:00',views:99,tags:['estate planning','woning','ouderenzorg'],beste:'vbf-087-a1',
  titel:'Woning en eigen bijdrage zorg bij opname',
  body:`Een oudere klant gaat mogelijk naar een zorginstelling. De kinderen vragen of de woning meetelt voor de eigen bijdrage. Wat weten jullie?`,
  antwoorden:[
   {id:'vbf-087-a1',auteur:'u2',datum:'2026-08-16T12:07:00',rA:{},rAdv:{},body:`Voor de eigen bijdrage wordt onder meer gekeken naar inkomen en een deel van het vermogen. De eigen woning wordt in sommige situaties anders behandeld. Controleer de actuele regels.
Leg vast dat je dit hebt besproken en verwijs naar het CAK of een gespecialiseerde adviseur.`}
  ]},
 {id:'vbf-088',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-08-19T07:30:00',views:543,tags:['estate planning','overlijden','box 3'],beste:'vbf-088-a1',
  titel:'Erven van een vakantiewoning en box 3',
  body:`Een klant heeft samen met zijn broer een vakantiewoning geërfd. Hoe valt die in box 3?`,
  antwoorden:[
   {id:'vbf-088-a1',auteur:'u2',datum:'2026-08-19T09:50:00',rA:{},rAdv:{},body:`De vakantiewoning valt in box 3 voor ieder voor zijn aandeel. Een eventuele schuld kan worden afgetrokken boven de schuldendrempel. Controleer de actuele regels.
Leg vast welke afspraken de broers hebben over gebruik en kosten.`}
  ]},
 {id:'vbf-089',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-08-24T09:10:00',views:597,tags:['estate planning','woning','gelijke behandeling'],beste:'vbf-089-a1',
  titel:'Woning naar één kind: gelijke behandeling regelen',
  body:`Ouders willen dat één kind later de woning krijgt, maar de andere kinderen moeten evenveel krijgen. Hoe adviseren jullie hierover?`,
  antwoorden:[
   {id:'vbf-089-a1',auteur:'u5',datum:'2026-08-25T02:41:00',rA:{u4:5},rAdv:{},body:`Dat is te regelen in een testament, bijvoorbeeld via een toedeling met verrekening. Het kind dat de woning krijgt, betaalt dan de anderen uit of ontvangt minder uit de overige nalatenschap.
Leg de wens vast in het dossier en verwijs naar de notaris.`}
  ]},
 {id:'vbf-090',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-09-01T13:40:00',views:496,tags:['estate planning','schenking','box 3'],beste:'vbf-090-a1',
  titel:'Schenken om box 3 te verlagen',
  body:`Klanten vragen of schenken aan kinderen de box 3-heffing verlaagt. Wat zeggen jullie?`,
  antwoorden:[
   {id:'vbf-090-a1',auteur:'u2',datum:'2026-09-01T15:43:00',rA:{u7:5},rAdv:{},body:`Schenken verlaagt het vermogen van de ouders op de peildatum, waardoor hun box 3-heffing daalt. Het vermogen komt wel bij de kinderen in box 3, maar zij hebben hun eigen heffingsvrije vermogen. Daarnaast speelt de schenkbelasting.
Leg de doelen vast en houd rekening met de eigen financiële buffer van de ouders.`}
  ]},
 {id:'vbf-091',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-09-02T12:50:00',views:531,tags:['estate planning','pensioen','woning'],beste:null,
  titel:'Hypotheek na pensioen houden voor nalatenschap',
  body:`Een gepensioneerd stel wil de hypotheek niet aflossen, zodat het spaargeld voor de kinderen blijft. Is dat fiscaal verstandig?`,
  antwoorden:[
   {id:'vbf-091-a1',auteur:'u2',datum:'2026-09-02T21:55:00',rA:{u1:5,u5:5},rAdv:{u1:5},body:`Dat hangt af van de netto rente, het rendement op het spaargeld en de box 3-heffing. Voor de kinderen maakt het uiteindelijk niet zoveel uit: de schuld vermindert de nalatenschap. Het gaat dus vooral om het netto voordeel tijdens het leven van de ouders.
Leg de afweging vast en bespreek de betaalbaarheid.`}
  ]},
 {id:'vbf-092',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-09-12T10:25:00',views:193,tags:['ORV','estate planning','langstlevende'],beste:'vbf-092-a1',
  titel:'ORV als onderdeel van estate planning rond de woning',
  body:`Een klant wil dat de langstlevende partner in de woning kan blijven wonen. Hoe adviseren jullie de ORV?`,
  antwoorden:[
   {id:'vbf-092-a1',auteur:'u3',datum:'2026-09-12T18:07:00',rA:{u4:5,u2:4,u1:4,u6:4},rAdv:{u2:4,u1:4,u6:4},body:`Wij bepalen het tekort dat ontstaat als een partner overlijdt. Daarbij nemen we het nabestaandenpensioen en andere inkomsten mee. Op basis daarvan bepalen we het bedrag van de ORV.
- Leg vast welke uitgangspunten zijn gebruikt.
- Bespreek of de ORV kruislings moet.
Controleer de acceptatievoorwaarden van de verzekeraar.`}
  ]},
 {id:'vbf-093',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-09-13T09:10:00',views:96,tags:['estate planning','overlijden','testament'],beste:'vbf-093-a1',
  titel:'Testament regelen bij aankoop van een woning door samenwoners',
  body:`Een jong stel koopt een eerste woning. Ze hebben geen testament. Bespreken jullie dat?`,
  antwoorden:[
   {id:'vbf-093-a1',auteur:'u5',datum:'2026-09-13T14:18:00',rA:{u8:5,u4:3,u1:5},rAdv:{u8:5},body:`Ja, bij ongehuwd samenwonenden altijd. Zonder testament erft de partner niets. Een testament, een samenlevingscontract met verblijvingsbeding en een ORV zijn de drie basisonderdelen.
Leg vast dat je het hebt besproken en of de klant actie onderneemt.`},
   {id:'vbf-093-a2',auteur:'u8',datum:'2026-09-13T19:07:00',rA:{u1:3,u5:3,u2:4,u7:3},rAdv:{u1:3,u2:4},body:`Vastleggen dat je het risico hebt benoemd, is belangrijk voor je zorgplicht. Ook als de klant kiest om niets te doen. Noteer daarom ook expliciet als de klant afziet van een testament of samenlevingscontract.`}
  ]},
 {id:'vbf-094',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-09-16T12:45:00',views:469,tags:['erfbelasting','schenking','woning'],beste:'vbf-094-a1',
  titel:'Woning met korting aan kind en schenkbelasting',
  body:`Ouders verkopen hun woning aan hun kind tegen een lagere prijs dan de marktwaarde. Hoe wordt het verschil fiscaal behandeld?`,
  antwoorden:[
   {id:'vbf-094-a1',auteur:'u2',datum:'2026-09-16T20:42:00',rA:{u1:4,u4:5,u3:5},rAdv:{u1:4,u3:5},body:`Het verschil tussen de marktwaarde en de koopprijs kan als schenking worden gezien. Laat de woning taxeren. Controleer de actuele regels.
Leg vast welke waarde en welke prijs zijn gehanteerd.`}
  ]},
 {id:'vbf-095',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-09-16T08:00:00',views:157,tags:['estate planning','box 3','schenken op papier'],beste:'vbf-095-a1',
  titel:'Schenken op papier en de rente',
  body:`Ouders willen op papier schenken aan hun kinderen. Welke voorwaarden gelden voor de rente?`,
  antwoorden:[
   {id:'vbf-095-a1',auteur:'u2',datum:'2026-09-16T11:44:00',rA:{u6:5},rAdv:{},body:`Bij schenken op papier moet de rente jaarlijks worden betaald, en de rente moet minimaal het wettelijk voorgeschreven percentage zijn. Er is een notariële akte nodig. Controleer de actuele regels.
Leg vast dat de rente daadwerkelijk wordt betaald.`},
   {id:'vbf-095-a2',auteur:'u5',datum:'2026-09-16T23:38:00',rA:{u8:3,u7:5,u6:4},rAdv:{},body:`In de praktijk: de rente wordt betaald, de kinderen kunnen het geld terugschenken. Let op dat de terugschenking niet is afgesproken, anders kan het fiscaal anders worden beoordeeld.`}
  ]},
 {id:'vbf-096',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-09-17T11:05:00',views:156,tags:['erfbelasting','partner','woning'],beste:null,
  titel:'Erfbelasting op de woning bij ongehuwde partners zonder testament',
  body:`Een ongehuwde partner overlijdt. De woning was samen gekocht. Wat zijn de gevolgen voor de erfbelasting?`,
  antwoorden:[
   {id:'vbf-096-a1',auteur:'u2',datum:'2026-09-18T09:25:00',rA:{u5:5,u7:4,u1:4},rAdv:{u5:4,u7:5},body:`Zonder testament erft een ongehuwde partner niets. Het aandeel van de overledene in de woning gaat naar de wettelijke erfgenamen (kinderen, ouders of broers en zussen). De partner blijft wel hoofdelijk aansprakelijk voor de hele hypotheek.
Erfbelasting:
- De erfgenamen betalen erfbelasting over hun deel, met hun eigen vrijstelling.
- Is er een notarieel samenlevingscontract met een verblijvingsbeding, dan kan de partner het aandeel toch krijgen. Dat geldt als verkrijging voor de erfbelasting; de partnervrijstelling hangt af van voorwaarden zoals de duur van het samenwonen. Controleer die bij belastingdienst.nl.
- Een ORV-uitkering kan ook belast zijn, afhankelijk van wie premie betaalde.
Advies voor de toekomst: samenlevingscontract en testamenten laten opstellen. Leg in het dossier vast dat je dit risico hebt besproken.`}
  ]},
 {id:'vbf-097',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-09-19T17:20:00',views:587,tags:['estate planning','box 3','hypotheek'],beste:'vbf-097-a1',
  titel:'Hypotheek gebruiken voor schenking aan kind',
  body:`Ouders willen hun hypotheek verhogen om een bedrag aan hun kind te schenken. Kan de rente fiscaal worden afgetrokken?`,
  antwoorden:[
   {id:'vbf-097-a1',auteur:'u2',datum:'2026-09-20T11:25:00',rA:{},rAdv:{},body:`Nee, de verhoging is geen eigenwoningschuld, omdat het geld niet wordt besteed aan de eigen woning. De lening valt in box 3.
Leg vast dat de rente niet aftrekbaar is.`},
   {id:'vbf-097-a2',auteur:'u4',datum:'2026-09-21T01:23:00',rA:{},rAdv:{},body:`Controleer de voorwaarden van de geldverstrekker voor de bestedingsdoelen van de verhoging. Sommige geldverstrekkers accepteren niet elk bestedingsdoel. Leg het doel van de verhoging daarom vast in het dossier.`}
  ]},
 {id:'vbf-098',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-09-23T18:05:00',views:332,tags:['estate planning','overdracht','familie'],beste:'vbf-098-a1',
  titel:'Overdrachtsbelasting bij overdracht van de woning aan kind',
  body:`Een woning wordt overgedragen aan een kind. Is er overdrachtsbelasting verschuldigd?`,
  antwoorden:[
   {id:'vbf-098-a1',auteur:'u2',datum:'2026-09-24T06:35:00',rA:{u5:4,u8:5,u4:5},rAdv:{},body:`In de regel wel. De startersvrijstelling kan onder voorwaarden van toepassing zijn. Controleer de actuele voorwaarden.
Leg vast welke vrijstelling is toegepast.`}
  ]},
 {id:'vbf-099',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-09-29T18:10:00',views:379,tags:['estate planning','erfbelasting','langstlevende'],beste:null,
  titel:'Langstlevendetestament versus wettelijke verdeling',
  body:`Een klant vraagt of een langstlevendetestament beter is dan de wettelijke verdeling. Wat zeggen jullie?`,
  antwoorden:[
   {id:'vbf-099-a1',auteur:'u5',datum:'2026-09-30T03:34:00',rA:{u4:4},rAdv:{u4:4},body:`De wettelijke verdeling beschermt de langstlevende al, maar een testament biedt meer mogelijkheden. Denk aan rente op de vordering, executeur en andere afspraken.
Verwijs naar de notaris en leg vast dat je het hebt besproken.`}
  ]},
 {id:'vbf-100',cat:'fisc',auteur:null,naam:'',voorbeeld:true,datum:'2026-09-30T17:50:00',views:164,tags:['estate planning','woning','eigenaarschap'],beste:'vbf-100-a1',
  titel:'Woning op naam van kind met hypotheek van ouders',
  body:`Een kind koopt een woning en de ouders betalen een deel via een hypotheek op hun eigen woning. Wat zijn de risicos?`,
  antwoorden:[
   {id:'vbf-100-a1',auteur:'u2',datum:'2026-10-01T00:11:00',rA:{u5:5,u4:4},rAdv:{u5:5},body:`De ouders lopen het risico dat het geld niet terugkomt. Leg vast of het een lening of een schenking is.
Controleer de voorwaarden van de geldverstrekker voor beide hypotheken.`},
   {id:'vbf-100-a2',auteur:'u8',datum:'2026-10-01T16:39:00',rA:{},rAdv:{},body:`Belangrijk voor het dossier: leg de afspraken tussen ouders en kind vast, ook als het om familie gaat. Een korte schriftelijke overeenkomst voorkomt discussie, bijvoorbeeld bij een scheiding of overlijden.`}
  ]}
]);
